"""
bank_builders/pack_database.py
Generates 320+ questions for SQL and 220+ questions for MongoDB.
"""

from .common import make_q, parse_item

SQL_ITEMS = [('What is SQL and what is it used for?', 'SQL (Structured Query Language) is the standard language used to store, manipulate, and retrieve data in relational database management systems (RDBMS).', 'Easy', 'Concept', 'SELECT * FROM employees;', 'What are the common SQL database engines?'), ('What is the difference between SQL and MySQL?', 'SQL is the standard query language. MySQL is an open-source Relational Database Management System (RDBMS) that implements and executes SQL.', 'Easy', 'Comparison', '', 'Name three other popular RDBMS.'), ('What is a Relational Database Management System (RDBMS)?', 'A database system that organizes data into structured tables consisting of rows (records) and columns (attributes), enforcing relationships via keys.', 'Easy', 'Concept', '', 'What is a primary key?'), ('What is a Table, a Row, and a Column in SQL?', 'A Table is a structured entity containing data. A Row (tuple/record) represents a single entity instance. A Column (field/attribute) defines a specific data attribute.', 'Easy', 'Concept', '', 'What is NULL in SQL?'), ('What does NULL represent in SQL?', 'NULL represents missing, unknown, or not applicable data. It is not equivalent to zero, false, or an empty string.', 'Easy', 'Concept', 'SELECT * FROM users WHERE phone IS NULL;', 'Can you compare NULL with = NULL?'), ("Why does 'WHERE column = NULL' fail in SQL?", "Because NULL is an unknown state. Any equality comparison with NULL yields UNKNOWN (falsy). Always use 'IS NULL' or 'IS NOT NULL'.", 'Easy', 'Concept', 'SELECT * FROM users WHERE email IS NULL;', 'How do you check for non-null values?'), ('What is the basic syntax of a SELECT query in SQL?', 'SELECT column1, column2 FROM table_name WHERE condition ORDER BY column1;', 'Easy', 'Concept', 'SELECT id, name FROM students WHERE age > 18;', 'What does SELECT * do?'), ("Why should 'SELECT *' be avoided in production application queries?", '1. Fetches unnecessary columns (wastes network bandwidth and RAM). 2. Breaks queries if table schema adds columns. 3. Prevents covering index optimizations.', 'Easy', 'Best Practice', 'SELECT id, email FROM users; -- Better than SELECT *', 'What is column aliasing?'), ('How do you alias a column or table in SQL?', 'Use the AS keyword (optional in many SQL dialects): SELECT first_name AS fname FROM employees e;.', 'Easy', 'Practical', 'SELECT emp_id, salary * 12 AS annual_salary FROM employees;', 'Can aliases be used in WHERE clause?'), ("Why can't you use a column alias in the WHERE clause in SQL?", 'Because the WHERE clause is evaluated before the SELECT clause in SQL query execution order. Aliases do not exist yet when WHERE filters rows.', 'Intermediate', 'Concept', '', 'What is the logical execution order of an SQL query?'), ('What is the logical order of execution of an SQL query?', '1. FROM & JOIN. 2. WHERE. 3. GROUP BY. 4. HAVING. 5. SELECT. 6. DISTINCT. 7. ORDER BY. 8. LIMIT / OFFSET.', 'Intermediate', 'Concept', '', 'In which phase is HAVING evaluated?'), ('What does the DISTINCT keyword do in SQL?', 'DISTINCT removes duplicate rows from the query result set, returning only unique value combinations.', 'Easy', 'Concept', 'SELECT DISTINCT department FROM employees;', 'Does DISTINCT apply to one column or all selected columns?'), ("Does 'SELECT DISTINCT col1, col2' apply to col1 only or the pair?", 'It applies to the entire combination of selected columns: rows are only duplicate if both col1 and col2 match.', 'Intermediate', 'Concept', 'SELECT DISTINCT city, state FROM addresses;', 'What does WHERE clause do?'), ('What is the WHERE clause used for in SQL?', 'The WHERE clause filters rows based on a specified boolean condition before any grouping occurs.', 'Easy', 'Concept', 'SELECT * FROM products WHERE price < 50;', 'What logical operators are supported in WHERE?'), ('What are the AND, OR, and NOT logical operators in SQL?', 'AND requires all conditions to be true. OR requires at least one condition to be true. NOT negates a condition.', 'Easy', 'Concept', "SELECT * FROM orders WHERE status = 'shipped' AND total > 100;", 'What is operator precedence between AND and OR?'), ('What is the operator precedence between AND and OR in SQL?', 'AND has higher precedence than OR. Always use parentheses (condition1 OR condition2) AND condition3 to avoid unintended filtering bugs.', 'Easy', 'Best Practice', "SELECT * FROM items WHERE (category = 'Book' OR category = 'Toy') AND price < 20;", 'What does BETWEEN operator do?'), ('What does the BETWEEN operator do in SQL?', 'BETWEEN filters values within an inclusive range: WHERE age BETWEEN 18 AND 25 (includes both 18 and 25).', 'Easy', 'Concept', 'SELECT * FROM employees WHERE salary BETWEEN 30000 AND 60000;', 'Is BETWEEN inclusive or exclusive?'), ('What does the IN operator do in SQL?', 'The IN operator allows specifying multiple discrete values in a WHERE clause, acting as shorthand for multiple OR conditions.', 'Easy', 'Concept', "SELECT * FROM customers WHERE country IN ('USA', 'Canada', 'UK');", 'What does NOT IN do?'), ('What happens if a NOT IN list contains a NULL value in SQL?', "If the subquery or list contains NULL, 'NOT IN' evaluates to UNKNOWN and returns ZERO rows! Use NOT EXISTS or filter out NULLs.", 'Advanced', 'Scenario', 'SELECT * FROM t1 WHERE id NOT IN (1, 2, NULL); -- Returns empty set!', 'Why does NOT IN fail with NULL?'), ('What is the LIKE operator used for in SQL?', 'The LIKE operator searches for a specified pattern in a column using wildcards (% for zero or more characters, _ for exactly one character).', 'Easy', 'Concept', "SELECT * FROM users WHERE name LIKE 'J%';", 'What wildcard matches a single character?'), ("What is the difference between '%' and '_' wildcards in SQL LIKE?", '% matches zero, one, or multiple characters. _ matches exactly one single character.', 'Easy', 'Comparison', "SELECT * FROM codes WHERE code LIKE 'A_C'; -- Matches ABC, A1C", 'How do you do case-insensitive search?'), ('How do you perform a case-insensitive pattern search in SQL?', "Use ILIKE in PostgreSQL, or use LOWER(column) LIKE LOWER('pattern') in MySQL/standard SQL.", 'Easy', 'Practical', "SELECT * FROM users WHERE LOWER(email) LIKE '%@gmail.com';", 'What does ORDER BY do?'), ('What is the ORDER BY clause used for in SQL?', 'ORDER BY sorts the result set by one or more columns in ascending (ASC, default) or descending (DESC) order.', 'Easy', 'Concept', 'SELECT * FROM products ORDER BY price DESC;', 'Can you sort by multiple columns?'), ('How do you sort by multiple columns in SQL?', 'Separate column names with commas: ORDER BY department ASC, salary DESC (sorts by department first, then by salary within department).', 'Easy', 'Practical', 'SELECT * FROM employees ORDER BY department_id ASC, salary DESC;', 'Where do NULL values appear in sorting?'), ('Where do NULL values appear in ORDER BY in SQL?', 'In MySQL, NULLs appear first in ASC. In PostgreSQL/Oracle, NULLS LAST or NULLS FIRST can be explicitly specified: ORDER BY salary ASC NULLS LAST.', 'Intermediate', 'Concept', 'SELECT * FROM employees ORDER BY commission ASC NULLS LAST;', 'What does LIMIT / OFFSET do?'), ('What does LIMIT and OFFSET do in SQL?', 'LIMIT constrains the number of rows returned. OFFSET skips a specified number of rows before beginning to return rows (used for pagination).', 'Easy', 'Concept', 'SELECT * FROM products ORDER BY id LIMIT 10 OFFSET 20; -- Page 3', 'What is the syntax for LIMIT in SQL Server / Oracle?'), ('How is pagination written in SQL Server and Oracle?', 'SQL Server uses: OFFSET 20 ROWS FETCH NEXT 10 ROWS ONLY. Oracle uses FETCH FIRST 10 ROWS ONLY.', 'Intermediate', 'Comparison', '', 'What does COALESCE() function do in SQL?'), ('What does the COALESCE(val1, val2, ...) function do in SQL?', 'COALESCE returns the first non-NULL value in its argument list. If all arguments are NULL, it returns NULL.', 'Easy', 'Concept', "SELECT COALESCE(phone, mobile, 'No Phone') AS contact FROM users;", 'How does IFNULL differ from COALESCE?'), ('What is the difference between IFNULL() and COALESCE()?', 'IFNULL(a, b) accepts exactly two arguments (MySQL specific). COALESCE(a, b, c, ...) is ANSI SQL standard and accepts arbitrary arguments.', 'Easy', 'Comparison', 'SELECT IFNULL(discount, 0) FROM products;', 'What does NULLIF(a, b) do?'), ('What does the NULLIF(expr1, expr2) function do in SQL?', 'NULLIF returns NULL if expr1 equals expr2; otherwise, it returns expr1. Commonly used to prevent division-by-zero errors: val / NULLIF(total, 0).', 'Intermediate', 'Concept', 'SELECT sales / NULLIF(target, 0) FROM targets;', 'How does NULLIF prevent division by zero?'), ('How do you prevent division by zero in SQL?', 'Wrap the divisor in NULLIF(divisor, 0): dividing by NULL returns NULL instead of throwing a runtime error.', 'Easy', 'Practical', 'SELECT revenue / NULLIF(units_sold, 0) AS avg_price FROM sales;', 'What does CASE WHEN statement do?'), ('What is the CASE statement in SQL?', 'The CASE statement provides conditional if-then-else logic within SQL expressions: CASE WHEN condition THEN result ELSE other END.', 'Easy', 'Concept', "SELECT name, salary,\n  CASE\n    WHEN salary > 50000 THEN 'High'\n    WHEN salary > 30000 THEN 'Medium'\n    ELSE 'Low'\n  END AS salary_bracket\nFROM employees;", 'Can CASE statements be used in ORDER BY?'), ('How can a CASE statement be used in an ORDER BY clause?', "To implement custom non-alphabetical sorting: ORDER BY CASE status WHEN 'Urgent' THEN 1 WHEN 'Normal' THEN 2 ELSE 3 END.", 'Intermediate', 'Practical', "ORDER BY CASE priority WHEN 'High' THEN 1 WHEN 'Med' THEN 2 ELSE 3 END", 'What are the common SQL data types?'), ('What are the main SQL data types?', 'Numeric (INT, BIGINT, DECIMAL/NUMERIC, FLOAT), String (CHAR, VARCHAR, TEXT), Date/Time (DATE, TIME, TIMESTAMP), and Boolean (BOOLEAN).', 'Easy', 'Concept', '', 'What is the difference between CHAR and VARCHAR?'), ('What is the difference between CHAR(10) and VARCHAR(10) in SQL?', 'CHAR(10) is fixed-length (always consumes 10 characters, padding with spaces). VARCHAR(10) is variable-length (stores only actual characters + length byte).', 'Easy', 'Comparison', "CHAR(10) stores 'cat' as 'cat       ' (10 bytes)\nVARCHAR(10) stores 'cat' as 3 bytes", 'When should you use CHAR over VARCHAR?'), ('When should CHAR be used instead of VARCHAR?', "For fixed-length data where length is strictly uniform (e.g. 2-letter country codes 'US', postal pin codes, MD5/SHA256 hashes, UUIDs).", 'Easy', 'Best Practice', 'country_code CHAR(2)', 'What is the difference between FLOAT and DECIMAL?'), ('Why should currency amounts ALWAYS use DECIMAL/NUMERIC instead of FLOAT/DOUBLE?', 'FLOAT uses binary floating-point representation, causing rounding and precision errors (e.g. 0.1 + 0.2 = 0.30000000000000004). DECIMAL stores exact decimal numbers.', 'Easy', 'Best Practice', 'price DECIMAL(10, 2) -- 10 digits total, 2 after decimal', 'What does DECIMAL(10, 2) mean?'), ('What does DECIMAL(8, 2) mean in SQL?', '8 is precision (total number of digits). 2 is scale (digits after decimal point). The max value is 999999.99.', 'Easy', 'Concept', '', 'What is TIMESTAMP vs DATETIME?'), ('What is the difference between DATETIME and TIMESTAMP in MySQL?', 'DATETIME stores date/time as-is (1000-9999) without timezone conversion. TIMESTAMP stores UTC seconds (1970-2038) and converts to current session timezone.', 'Intermediate', 'Comparison', '', 'What is SQL Query MCQ: Which keyword retrieves unique values from a column?'), ('SQL Basics MCQ: Which keyword is used to return only different values?', 'Option B is correct. SELECT DISTINCT eliminates duplicates.', 'Easy', 'MCQ', '', {'A': 'UNIQUE', 'B': 'DISTINCT', 'C': 'DIFFERENT', 'D': 'INDIVIDUAL'}, 'B', 'Where is DISTINCT placed?'), ("SQL Basics MCQ: What is the result of 'SELECT 5 + NULL;'?", 'Option C is correct. Any arithmetic operation with NULL results in NULL.', 'Easy', 'MCQ', '', {'A': '5', 'B': '0', 'C': 'NULL', 'D': 'Error'}, 'C', 'Why does it yield NULL?'), ('SQL Basics MCQ: Which clause is used to filter records before grouping?', 'Option A is correct. WHERE filters before grouping; HAVING filters after grouping.', 'Easy', 'MCQ', '', {'A': 'WHERE', 'B': 'HAVING', 'C': 'FILTER', 'D': 'ORDER BY'}, 'A', 'What does HAVING filter?'), ("SQL Basics MCQ: What does the wildcard '_' represent in a LIKE query?", 'Option B is correct. The underscore represents exactly one single character.', 'Easy', 'MCQ', '', {'A': 'Zero or more characters', 'B': 'Exactly one character', 'C': 'Any digit', 'D': 'An escape character'}, 'B', 'What represents zero or more?'), ("SQL Basics Query: Write a query to find all employees whose name starts with 'A' and salary is greater than 50000.", "SELECT * FROM employees WHERE name LIKE 'A%' AND salary > 50000;", 'Easy', 'Coding', "SELECT * FROM employees\nWHERE name LIKE 'A%'\n  AND salary > 50000;", "How to find names ending with 'A'?"), ('SQL Basics Query: Write a query to fetch the 5 highest paid employees.', 'SELECT * FROM employees ORDER BY salary DESC LIMIT 5;', 'Easy', 'Coding', 'SELECT name, salary\nFROM employees\nORDER BY salary DESC\nLIMIT 5;', 'How do you fetch employees 6 to 10?'), ("SQL Basics Debugging: Why does 'SELECT * FROM users WHERE status = NULL' return 0 rows?", "Comparison with NULL using '=' always evaluates to UNKNOWN. Correct syntax is 'WHERE status IS NULL'.", 'Easy', 'Debugging', '-- WRONG: WHERE status = NULL\n-- CORRECT: WHERE status IS NULL', 'Why does = NULL return UNKNOWN?'), ("SQL Basics Debugging: Query: 'SELECT id, salary * 12 AS annual FROM emp WHERE annual > 50000;' fails. Why?", "The WHERE clause cannot use column aliases created in SELECT because WHERE executes before SELECT. Repeat expression: 'WHERE salary * 12 > 50000'.", 'Intermediate', 'Debugging', '-- CORRECT:\nSELECT id, salary * 12 AS annual\nFROM emp\nWHERE salary * 12 > 50000;', 'Can HAVING use aliases?'), ('What does the CONCAT() function do in SQL?', 'CONCAT(str1, str2, ...) joins two or more strings together into a single string.', 'Easy', 'Practical', "SELECT CONCAT(first_name, ' ', last_name) AS full_name FROM users;", 'What operator does PostgreSQL/SQLite use for concatenation?'), ('What is the concatenation operator in PostgreSQL, Oracle, and SQLite?', "The double pipe operator: '||' (e.g. first_name || ' ' || last_name).", 'Easy', 'Concept', "SELECT first_name || ' ' || last_name AS full_name FROM employees;", 'What does LENGTH() / LEN() do?'), ('What does LENGTH() function do in SQL?', 'It returns the length of a string in characters or bytes (LENGTH in MySQL/Postgres, LEN in SQL Server).', 'Easy', 'Practical', 'SELECT name, LENGTH(name) AS len FROM users;', 'What does TRIM() do?'), ('What does TRIM() function do in SQL?', 'TRIM removes leading and trailing spaces (or specified characters) from a string. LTRIM removes leading; RTRIM removes trailing.', 'Easy', 'Practical', "SELECT TRIM('  hello  '); -- 'hello'", 'What does UPPER and LOWER do?'), ('What do UPPER() and LOWER() functions do in SQL?', 'UPPER converts a string to uppercase letters; LOWER converts a string to lowercase letters.', 'Easy', 'Practical', 'SELECT UPPER(city) FROM addresses;', 'How do you extract a substring in SQL?'), ('How do you extract a portion of a string in SQL?', 'Use SUBSTRING(str, start, length) or SUBSTR(str, start, length). Note that SQL string indexing is 1-indexed!', 'Easy', 'Practical', "SELECT SUBSTRING('Database', 1, 4); -- 'Data'", 'Is SQL string index 0 or 1?'), ('Why is SQL string indexing 1-indexed rather than 0-indexed?', "SQL follows standard mathematical conventions where positions begin at 1. SUBSTRING('abc', 1, 1) returns 'a'.", 'Easy', 'Concept', '', 'What does ROUND() function do?'), ('What does the ROUND(number, decimals) function do in SQL?', 'ROUND rounds a numeric field to the specified number of decimal places (ROUND(12.345, 2) returns 12.35).', 'Easy', 'Practical', 'SELECT ROUND(avg_score, 2) FROM student_grades;', 'What does CEIL / FLOOR do?'), ('What is the difference between CEIL() and FLOOR() in SQL?', 'CEIL(x) rounds a number up to the nearest integer. FLOOR(x) rounds a number down to the nearest integer.', 'Easy', 'Comparison', 'CEIL(4.2) -> 5\nFLOOR(4.9) -> 4', 'What does MOD() do?'), ('What does MOD(n, m) or % do in SQL?', 'Returns the remainder of dividing n by m (e.g. MOD(10, 3) returns 1).', 'Easy', 'Practical', 'SELECT * FROM numbers WHERE id % 2 = 0; -- Even ids', 'What does NOW() or CURRENT_TIMESTAMP return?'), ('How do you get the current date and time in SQL?', 'Use NOW(), CURRENT_TIMESTAMP, or GETDATE() (SQL Server).', 'Easy', 'Practical', 'SELECT CURRENT_TIMESTAMP;', 'How do you get only current date without time?'), ('How do you get the current date without time in SQL?', 'Use CURRENT_DATE or CURDATE().', 'Easy', 'Practical', 'SELECT CURRENT_DATE;', 'How do you calculate date difference in SQL?'), ('How do you calculate the difference between two dates in SQL?', 'DATEDIFF(date1, date2) in MySQL, or (date1 - date2) in PostgreSQL.', 'Easy', 'Practical', 'SELECT DATEDIFF(NOW(), hire_date) AS days_worked FROM employees;', 'What does DATE_ADD do?'), ('What are the 5 sub-languages of SQL?', '1. DDL (Data Definition Language). 2. DML (Data Manipulation Language). 3. DQL (Data Query Language). 4. DCL (Data Control Language). 5. TCL (Transaction Control Language).', 'Easy', 'Concept', '', 'What commands belong to DDL?'), ('Which commands belong to DDL (Data Definition Language)?', 'CREATE, ALTER, DROP, TRUNCATE, and RENAME. They define and modify database schema structures.', 'Easy', 'Concept', 'CREATE TABLE users (id INT PRIMARY KEY);', 'Which commands belong to DML?'), ('Which commands belong to DML (Data Manipulation Language)?', 'INSERT, UPDATE, and DELETE. They manipulate data records stored inside tables.', 'Easy', 'Concept', "INSERT INTO users (name) VALUES ('Alice');", 'Which commands belong to DCL?'), ('Which commands belong to DCL (Data Control Language)?', 'GRANT and REVOKE. They manage user permissions and access rights on database objects.', 'Easy', 'Concept', 'GRANT SELECT ON users TO reader_role;', 'Which commands belong to TCL?'), ('Which commands belong to TCL (Transaction Control Language)?', 'COMMIT, ROLLBACK, and SAVEPOINT. They manage transactions to ensure ACID compliance.', 'Easy', 'Concept', 'COMMIT;\nROLLBACK;', 'How do you insert a single row into a table?'), ('How do you insert a single row into a table in SQL?', 'INSERT INTO table_name (col1, col2) VALUES (val1, val2);', 'Easy', 'Practical', "INSERT INTO customers (name, email) VALUES ('John', 'john@test.com');", 'How do you insert multiple rows in one query?'), ('How do you insert multiple rows in a single SQL statement (bulk insert)?', 'Chain multiple value sets separated by commas: INSERT INTO table (col) VALUES (val1), (val2), (val3);.', 'Easy', 'Practical', "INSERT INTO tags (name) VALUES ('JS'), ('React'), ('Node');", 'Why is bulk insert faster than individual inserts?'), ('Why is multi-row bulk insert faster than multiple single inserts?', 'It avoids round-trip network latency, parses query syntax once, and executes within a single internal transaction instead of multiple commits.', 'Intermediate', 'Performance', '', 'What is INSERT INTO SELECT?'), ('How do you copy data from one table to another in SQL?', 'Use INSERT INTO target_table (cols) SELECT cols FROM source_table WHERE condition;.', 'Easy', 'Practical', "INSERT INTO archived_orders SELECT * FROM orders WHERE created_at < '2025-01-01';", 'How do you update existing records in SQL?'), ('What is the syntax for the UPDATE statement in SQL?', 'UPDATE table_name SET col1 = val1, col2 = val2 WHERE condition;.', 'Easy', 'Practical', "UPDATE employees SET salary = salary * 1.10 WHERE department = 'IT';", 'What happens if you execute UPDATE without a WHERE clause?'), ('What catastrophic mistake occurs if UPDATE is run without a WHERE clause?', 'Every single row in the entire table is updated with the new values!', 'Easy', 'Scenario', '-- DANGEROUS: Updates EVERY user!\nUPDATE users SET is_active = false;', 'How do you safely test an UPDATE before executing?'), ('How can you safely verify an UPDATE before running it in production?', '1. Run a SELECT with the exact same WHERE clause to verify matching rows. 2. Wrap in a transaction: BEGIN TRANSACTION; UPDATE ...; check count; ROLLBACK or COMMIT.', 'Easy', 'Best Practice', 'BEGIN;\nUPDATE accounts SET balance = 0 WHERE id = 12;\n-- Check result\nROLLBACK; -- Undo if mistake', 'What does the DELETE statement do?'), ('What is the syntax for DELETE in SQL?', 'DELETE FROM table_name WHERE condition;.', 'Easy', 'Practical', 'DELETE FROM sessions WHERE expired_at < NOW();', 'What happens if you run DELETE without a WHERE clause?'), ('What happens if you run DELETE without a WHERE clause in SQL?', 'All rows in the table are deleted, but the table structure and column definitions remain intact.', 'Easy', 'Scenario', 'DELETE FROM logs; -- Empties the table', 'What is the difference between DELETE, TRUNCATE, and DROP?'), ('What are the differences between DELETE, TRUNCATE, and DROP?', 'DELETE: DML, removes rows row-by-row, supports WHERE clause, can be rolled back, fires triggers. TRUNCATE: DDL, removes all rows instantly by deallocating pages, resets auto-increment, cannot use WHERE. DROP: DDL, destroys both the data AND the table structure completely.', 'Intermediate', 'Comparison', '', 'Can TRUNCATE be rolled back in SQL?'), ('Can TRUNCATE be rolled back?', 'In PostgreSQL and SQL Server, TRUNCATE can be rolled back inside an explicit transaction! In MySQL, DDL causes an implicit commit and cannot be rolled back.', 'Advanced', 'Concept', '', 'Why is TRUNCATE faster than DELETE?'), ('Why is TRUNCATE substantially faster than DELETE for large tables?', 'DELETE writes individual undo/redo logs for every deleted row and executes triggers. TRUNCATE simply deallocates the underlying disk data pages without row-by-row logging.', 'Intermediate', 'Performance', '', 'What is CREATE TABLE syntax?'), ('What is the syntax to create a table in SQL?', 'CREATE TABLE table_name (col1 datatype constraint, col2 datatype constraint);', 'Easy', 'Practical', 'CREATE TABLE users (\n  id INT PRIMARY KEY AUTO_INCREMENT,\n  email VARCHAR(255) NOT NULL UNIQUE,\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);', 'What is AUTO_INCREMENT / SERIAL?'), ('What is AUTO_INCREMENT (or SERIAL in Postgres / IDENTITY in SQL Server)?', 'A column property that automatically generates unique sequential integer IDs for newly inserted rows.', 'Easy', 'Concept', 'id SERIAL PRIMARY KEY -- PostgreSQL\nid INT AUTO_INCREMENT PRIMARY KEY -- MySQL', 'What is the DEFAULT constraint?'), ('What does the DEFAULT constraint do in SQL?', 'It provides a fallback default value for a column when an INSERT statement does not specify a value.', 'Easy', 'Concept', "status VARCHAR(20) DEFAULT 'pending'", 'What does the NOT NULL constraint do?'), ('What does the NOT NULL constraint enforce?', 'It prevents a column from accepting NULL values, guaranteeing that every record must contain a valid value.', 'Easy', 'Concept', 'name VARCHAR(100) NOT NULL', 'What does the UNIQUE constraint enforce?'), ('What does the UNIQUE constraint enforce in SQL?', 'It guarantees that all values in a column (or group of columns) are distinct across all rows. Most databases allow multiple NULLs in a UNIQUE column (except SQL Server).', 'Easy', 'Concept', 'ALTER TABLE users ADD CONSTRAINT uq_email UNIQUE (email);', 'Can a UNIQUE column accept NULL values?'), ('Can a UNIQUE column contain NULL values?', 'Yes, in ANSI SQL and PostgreSQL/MySQL, multiple rows can have NULL because NULL != NULL. In SQL Server, only one NULL is permitted in a UNIQUE column.', 'Intermediate', 'Concept', '', 'What is a Primary Key in SQL?'), ('What is a Primary Key and what constraints does it enforce?', 'A Primary Key uniquely identifies each row in a table. It strictly enforces both UNIQUE and NOT NULL constraints. A table can have at most one primary key.', 'Easy', 'Concept', 'PRIMARY KEY (id)', 'Can a table have multiple primary keys?'), ('Can a table have multiple Primary Keys?', 'No. A table can have only ONE primary key. However, that primary key can consist of multiple columns (Composite Primary Key).', 'Easy', 'Concept', 'PRIMARY KEY (order_id, product_id) -- Composite Key', 'What is a Composite Key?'), ('What is a Composite Primary Key?', 'A primary key composed of two or more columns together that uniquely identify a row (e.g. order_id + product_id in order_items).', 'Intermediate', 'Concept', 'CREATE TABLE order_items (\n  order_id INT,\n  product_id INT,\n  quantity INT,\n  PRIMARY KEY (order_id, product_id)\n);', 'What is a Foreign Key?'), ('What is a Foreign Key in SQL?', 'A Foreign Key is a column (or columns) in one table that references the Primary Key (or Unique key) of another table, enforcing referential integrity.', 'Easy', 'Concept', 'FOREIGN KEY (user_id) REFERENCES users(id)', 'What is Referential Integrity?'), ('What is Referential Integrity in relational databases?', 'A rule ensuring that foreign key values always point to an existing, valid primary key record in the referenced parent table (no orphaned records).', 'Easy', 'Concept', '', 'What is ON DELETE CASCADE?'), ("What does 'ON DELETE CASCADE' do in foreign keys?", 'When a parent row is deleted, all child rows in referencing tables with matching foreign keys are automatically deleted by the database.', 'Easy', 'Concept', 'FOREIGN KEY (author_id) REFERENCES authors(id) ON DELETE CASCADE', 'What is ON DELETE SET NULL?'), ("What does 'ON DELETE SET NULL' do in foreign keys?", 'When the parent row is deleted, the foreign key column in all matching child rows is automatically set to NULL (the foreign key column must be nullable).', 'Intermediate', 'Concept', 'FOREIGN KEY (manager_id) REFERENCES employees(id) ON DELETE SET NULL', 'What is ON DELETE RESTRICT / NO ACTION?'), ("What does 'ON DELETE RESTRICT' (or NO ACTION) do?", 'It rejects and blocks the deletion of a parent row if any child rows reference it, throwing a foreign key violation error.', 'Easy', 'Concept', '', 'What is the CHECK constraint in SQL?'), ('What does the CHECK constraint do in SQL?', 'CHECK ensures that all values in a column satisfy a specific boolean condition before allowing INSERT or UPDATE.', 'Easy', 'Concept', 'CREATE TABLE accounts (\n  balance DECIMAL(10,2) CHECK (balance >= 0)\n);', 'Give an example of a CHECK constraint.'), ('How do you add a new column to an existing table in SQL?', 'Use ALTER TABLE table_name ADD COLUMN column_name datatype constraint;.', 'Easy', 'Practical', 'ALTER TABLE users ADD COLUMN phone VARCHAR(20);', 'How do you drop a column from a table?'), ('How do you remove an existing column from a table?', 'Use ALTER TABLE table_name DROP COLUMN column_name;.', 'Easy', 'Practical', 'ALTER TABLE users DROP COLUMN phone;', 'How do you rename a table or column?'), ('How do you rename a column or table in SQL?', 'ALTER TABLE table_name RENAME COLUMN old_name TO new_name; ALTER TABLE old_name RENAME TO new_name;.', 'Easy', 'Practical', 'ALTER TABLE employees RENAME COLUMN dept TO department;', 'What is CREATE TABLE AS SELECT (CTAS)?'), ('What does CREATE TABLE AS SELECT (CTAS) do?', 'It creates a new table and populates it immediately with the result set of a SELECT query.', 'Intermediate', 'Practical', 'CREATE TABLE active_users AS\nSELECT * FROM users WHERE is_active = true;', 'Does CTAS copy primary keys and indexes?'), ('Does CREATE TABLE AS SELECT copy indexes and foreign key constraints?', 'No! CTAS copies column definitions and row data, but does NOT copy primary keys, indexes, triggers, or foreign key constraints.', 'Intermediate', 'Concept', '', 'CRUD MCQ: Which SQL command removes all rows from a table, cannot use a WHERE clause, and resets auto-increment?'), ('CRUD MCQ: Which command deletes all rows without row-by-row logging and resets identity?', 'Option B is correct. TRUNCATE resets auto-increment and deallocates pages.', 'Easy', 'MCQ', '', {'A': 'DELETE', 'B': 'TRUNCATE', 'C': 'DROP', 'D': 'REMOVE'}, 'B', 'Can DELETE use a WHERE clause?'), ('CRUD MCQ: What happens when an INSERT query specifies a duplicate value for a UNIQUE column?', 'Option C is correct. The database throws a unique constraint violation error.', 'Easy', 'MCQ', '', {'A': 'Silently ignores', 'B': 'Overwrites the old row', 'C': 'Throws a constraint violation error', 'D': 'Creates a copy with incremented id'}, 'C', 'How do you handle duplicates in MySQL?'), ('Constraints MCQ: What two constraints are automatically enforced on any PRIMARY KEY column?', 'Option A is correct. UNIQUE and NOT NULL.', 'Easy', 'MCQ', '', {'A': 'UNIQUE and NOT NULL', 'B': 'UNIQUE and DEFAULT', 'C': 'CHECK and FOREIGN KEY', 'D': 'INDEX and AUTO_INCREMENT'}, 'A', 'Can primary key have null?'), ('Constraints MCQ: What foreign key action automatically deletes child records when the referenced parent record is deleted?', 'Option D is correct. ON DELETE CASCADE deletes children.', 'Easy', 'MCQ', '', {'A': 'SET DEFAULT', 'B': 'RESTRICT', 'C': 'NO ACTION', 'D': 'CASCADE'}, 'D', 'What does RESTRICT do?'), ('CRUD Coding: Write an SQL query to increase the salary of all employees in department 10 by 15%.', 'UPDATE employees SET salary = salary * 1.15 WHERE department_id = 10;', 'Easy', 'Coding', 'UPDATE employees\nSET salary = salary * 1.15\nWHERE department_id = 10;', 'What status code or row count is returned?'), ("CRUD Coding: Write an SQL query to insert a new product with name 'Laptop', price 999.99, and stock 50.", "INSERT INTO products (name, price, stock) VALUES ('Laptop', 999.99, 50);", 'Easy', 'Coding', "INSERT INTO products (name, price, stock)\nVALUES ('Laptop', 999.99, 50);", 'How do you return the newly created id in Postgres?'), ('How do you return the newly created ID in PostgreSQL INSERT statements?', "Append 'RETURNING id' to the INSERT statement: INSERT INTO users (name) VALUES ('Bob') RETURNING id;.", 'Easy', 'Practical', 'INSERT INTO orders (total) VALUES (150.00) RETURNING id;', 'What is UPSERT in SQL?'), ('What is UPSERT (INSERT ON CONFLICT / ON DUPLICATE KEY UPDATE)?', "An operation that inserts a new row if it doesn't exist, or updates the existing row if a unique key conflict occurs.", 'Intermediate', 'Concept', '-- PostgreSQL:\nINSERT INTO counters (id, count) VALUES (1, 1)\nON CONFLICT (id) DO UPDATE SET count = counters.count + 1;\n-- MySQL:\nINSERT INTO counters (id, count) VALUES (1, 1)\nON DUPLICATE KEY UPDATE count = count + 1;', 'Why is UPSERT atomic?'), ('CRUD Debugging: A developer wrote: DELETE FROM employees WHERE salary < 30000; but wanted to test first. What mistake happened?', 'They executed DELETE directly without running SELECT first, permanently deleting matching records. Always run SELECT before DELETE.', 'Easy', 'Debugging', '-- Always test first:\nSELECT count(*) FROM employees WHERE salary < 30000;', 'How to undo if in a transaction?'), ('What is an orphaned record in a database?', 'A child record whose foreign key references a parent record that no longer exists (prevented by foreign key constraints).', 'Easy', 'Concept', '', 'What is a surrogate key vs natural key?'), ('What is the difference between a Natural Key and a Surrogate Key?', 'Natural Key: real-world business identifier with intrinsic meaning (SSN, ISBN, email). Surrogate Key: artificially generated system identifier without business meaning (auto-increment INT, UUID).', 'Intermediate', 'Comparison', '', 'Why are surrogate integer/UUID keys preferred as primary keys?'), ('Why are surrogate keys generally preferred over natural keys for Primary Keys?', 'Natural keys can change (e.g. user changes their email address), which breaks foreign keys across many tables. Surrogate keys are immutable and compact.', 'Intermediate', 'Best Practice', '', 'What is a UUID and why is it used as a primary key?'), ('What are the advantages and disadvantages of UUIDs as primary keys?', 'Advantage: Globally unique across distributed systems without central coordination. Disadvantage: 16 bytes (larger than 4/8-byte INTs) and random insertion causes B-tree index page fragmentation.', 'Intermediate', 'Comparison', 'id UUID DEFAULT gen_random_uuid() PRIMARY KEY', 'What is UUIDv7?'), ('What are aggregate functions in SQL?', 'Aggregate functions perform a calculation on a set of column values and return a single scalar value. They ignore NULL values (except COUNT(*)).', 'Easy', 'Concept', 'SELECT AVG(salary), MAX(salary) FROM employees;', 'Name the 5 standard aggregate functions.'), ('Name the 5 standard ANSI SQL aggregate functions.', '1. COUNT(): counts rows/values. 2. SUM(): sums values. 3. AVG(): calculates average. 4. MIN(): finds minimum. 5. MAX(): finds maximum.', 'Easy', 'Concept', '', 'What is the difference between COUNT(*) and COUNT(column)?'), ('What is the crucial difference between COUNT(*) and COUNT(column_name)?', 'COUNT(*) counts all rows including rows with NULLs. COUNT(column_name) counts only rows where that specific column is NOT NULL.', 'Easy', 'Comparison', 'SELECT COUNT(*), COUNT(commission) FROM employees;', 'When would COUNT(*) and COUNT(col) give different results?'), ('What does COUNT(DISTINCT column) do in SQL?', 'It counts only unique, non-null values in the specified column.', 'Easy', 'Practical', 'SELECT COUNT(DISTINCT department_id) FROM employees;', 'Does COUNT(DISTINCT) ignore NULL?'), ('Does COUNT(DISTINCT column) count NULL values?', 'No. Aggregate functions (including COUNT DISTINCT) ignore NULL values completely.', 'Easy', 'Concept', '', 'What does SUM() return if all rows in a column are NULL?'), ('What does SUM() return if a table is empty or all values in the column are NULL?', 'It returns NULL (not 0!). Wrap in COALESCE: COALESCE(SUM(amount), 0) to guarantee a zero value.', 'Intermediate', 'Concept', "SELECT COALESCE(SUM(amount), 0) FROM sales WHERE date = '2099-01-01';", 'Why does SUM return NULL?'), ('What does AVG() do with NULL values?', 'AVG() ignores NULL rows entirely from both the numerator (sum) and denominator (count).', 'Intermediate', 'Concept', '-- If values are: 10, 20, NULL\n-- AVG is (10 + 20) / 2 = 15, NOT (10 + 20) / 3 = 10', 'How do you include NULLs as 0 in AVG?'), ('How do you calculate the average including NULL values treated as 0?', 'Use COALESCE: AVG(COALESCE(bonus, 0)). This divides by the total row count rather than non-null count.', 'Intermediate', 'Practical', 'SELECT AVG(COALESCE(bonus, 0)) FROM employees;', 'What does MIN() and MAX() work on?'), ('Can MIN() and MAX() be used on text and date columns in SQL?', 'Yes! For text, MIN/MAX returns alphabetical extremes (A to Z). For dates, MIN returns oldest date and MAX returns most recent date.', 'Easy', 'Concept', 'SELECT MIN(hire_date), MAX(hire_date) FROM employees;', 'What is the GROUP BY clause used for?'), ('What does the GROUP BY clause do in SQL?', 'GROUP BY groups rows that share the same values in specified columns into summary rows (e.g. calculate total sales per department).', 'Easy', 'Concept', 'SELECT department, COUNT(*), AVG(salary)\nFROM employees\nGROUP BY department;', 'What is the rule regarding columns in SELECT when using GROUP BY?'), ('What is the single most important rule for the SELECT list when using GROUP BY?', 'Every column in the SELECT clause must EITHER be included in the GROUP BY clause OR be wrapped inside an aggregate function.', 'Easy', 'Concept', '-- INVALID:\nSELECT department, name, AVG(salary) FROM emp GROUP BY department;\n-- VALID:\nSELECT department, AVG(salary) FROM emp GROUP BY department;', 'Why is selecting non-aggregated columns invalid?'), ('Why is selecting a non-grouped, non-aggregated column invalid in standard SQL?', 'Because a group contains multiple rows with different values for that column; the database does not know which single row value to return.', 'Intermediate', 'Concept', '', 'What is the HAVING clause used for in SQL?'), ('What is the difference between WHERE and HAVING in SQL?', 'WHERE filters individual rows BEFORE any grouping occurs (cannot use aggregate functions). HAVING filters summarized groups AFTER grouping (can use aggregate functions).', 'Easy', 'Comparison', 'SELECT department, COUNT(*)\nFROM employees\nWHERE salary > 30000 -- filters rows\nGROUP BY department\nHAVING COUNT(*) > 5; -- filters groups', 'Can HAVING be used without GROUP BY?'), ('Can HAVING be used without a GROUP BY clause in SQL?', 'Yes! When used without GROUP BY, HAVING treats the entire table as a single summary group.', 'Intermediate', 'Concept', 'SELECT AVG(salary) FROM employees HAVING AVG(salary) > 50000;', 'Can WHERE use aggregate functions?'), ("Why can't aggregate functions (like SUM or AVG) be used in a WHERE clause?", 'Because the WHERE clause executes before rows are grouped and before aggregate functions are calculated.', 'Easy', 'Concept', '-- WRONG: WHERE COUNT(*) > 5\n-- CORRECT: HAVING COUNT(*) > 5', 'Can you group by multiple columns?'), ('How does grouping by multiple columns work in SQL?', 'GROUP BY col1, col2 groups rows where BOTH col1 and col2 match (e.g. total sales per region AND per year).', 'Easy', 'Practical', 'SELECT region, year, SUM(sales)\nFROM regional_sales\nGROUP BY region, year;', 'What is the result of GROUP BY with NULL values?'), ('How does GROUP BY handle NULL values in the grouping column?', 'All rows with NULL in the grouping column are gathered together into a single group.', 'Intermediate', 'Concept', 'SELECT department, COUNT(*) FROM emp GROUP BY department; -- NULL dept forms 1 group', 'Can you filter on aliases in HAVING?'), ('Can column aliases defined in SELECT be used in the HAVING clause?', 'In standard SQL, no; repeat the aggregate expression. However, MySQL and Snowflake permit using aliases in HAVING.', 'Intermediate', 'Concept', '-- Standard ANSI SQL:\nHAVING COUNT(*) > 10\n-- MySQL:\nHAVING total_users > 10', 'What is GROUP BY 1, 2?'), ("What does 'GROUP BY 1, 2' mean in SQL?", 'It groups by the 1st and 2nd columns listed in the SELECT clause (positional grouping shorthand).', 'Intermediate', 'Practical', 'SELECT department, job_title, COUNT(*) FROM emp GROUP BY 1, 2;', 'Why is positional grouping discouraged in production code?'), ("Why is 'GROUP BY 1, 2' considered bad practice in production code?", 'If someone changes the column order in the SELECT list, the grouping criteria silently changes without syntax error, causing subtle data bugs.', 'Intermediate', 'Best Practice', '', 'What is GROUPING SETS in SQL?'), ('What is GROUPING SETS in advanced SQL aggregation?', 'GROUPING SETS allows computing multiple different group aggregations in a single query (e.g. group by department, group by region, and grand total).', 'Advanced', 'Concept', 'GROUP BY GROUPING SETS ((department), (region), ());', 'What is ROLLUP in SQL?'), ('What does the ROLLUP operator do in GROUP BY?', 'ROLLUP creates hierarchical subtotals and a grand total row along the specified columns from right to left.', 'Advanced', 'Concept', 'GROUP BY ROLLUP (year, quarter, month);', 'What is CUBE in SQL?'), ('What does the CUBE operator do in GROUP BY?', 'CUBE generates subtotals for all possible combinations of the specified grouping columns (cross-tabulation).', 'Advanced', 'Concept', 'GROUP BY CUBE (category, region);', 'What is the difference between ROLLUP and CUBE?'), ('What is the difference between ROLLUP and CUBE?', 'ROLLUP generates hierarchical progressive aggregations (subtotals from top to bottom). CUBE generates all multidimensional combinations of aggregations.', 'Advanced', 'Comparison', '', 'What is the STRING_AGG / GROUP_CONCAT function?'), ('How do you concatenate column values from multiple rows into a single string within a group?', "Use GROUP_CONCAT(name SEPARATOR ', ') in MySQL, or STRING_AGG(name, ', ') in PostgreSQL/SQL Server.", 'Intermediate', 'Practical', "SELECT department_id, STRING_AGG(name, ', ') AS employees\nFROM employees\nGROUP BY department_id;", 'Give an example of GROUP_CONCAT in MySQL.'), ('What is the MySQL syntax for GROUP_CONCAT?', "SELECT department_id, GROUP_CONCAT(name ORDER BY name SEPARATOR '; ') FROM employees GROUP BY department_id;", 'Easy', 'Practical', "SELECT dept_id, GROUP_CONCAT(name SEPARATOR ', ') FROM emp GROUP BY dept_id;", 'What is the default character limit of GROUP_CONCAT in MySQL?'), ('What is the default character limit for GROUP_CONCAT in MySQL and how do you increase it?', 'Default is 1024 characters. Strings longer than this are truncated. Increase with: SET SESSION group_concat_max_len = 1000000;.', 'Intermediate', 'Practical', 'SET SESSION group_concat_max_len = 100000;', 'Aggregate MCQ: Which aggregate function counts rows including rows with NULL values?'), ('Aggregate MCQ: Which expression counts total rows including rows containing NULLs?', 'Option A is correct. COUNT(*) counts all rows regardless of NULLs.', 'Easy', 'MCQ', '', {'A': 'COUNT(*)', 'B': 'COUNT(column)', 'C': 'SUM(1)', 'D': 'COUNT(ALL)'}, 'A', 'Does COUNT(column) count null?'), ('Aggregate MCQ: Where must conditions containing aggregate functions (e.g. SUM(sales) > 10000) be placed?', 'Option B is correct. Aggregate conditions belong in the HAVING clause.', 'Easy', 'MCQ', '', {'A': 'WHERE', 'B': 'HAVING', 'C': 'GROUP BY', 'D': 'ORDER BY'}, 'B', "Why can't WHERE be used?"), ('Aggregate MCQ: What does SUM(price) return when a query finds zero matching rows?', 'Option C is correct. SUM returns NULL when no rows match.', 'Easy', 'MCQ', '', {'A': '0', 'B': '-1', 'C': 'NULL', 'D': 'Error'}, 'C', 'How do you make it return 0?'), ('Aggregate MCQ: What happens to rows with NULL values in the GROUP BY column?', 'Option D is correct. They are grouped together into a single group.', 'Easy', 'MCQ', '', {'A': 'Ignored completely', 'B': 'Throw an error', 'C': 'Form separate groups per row', 'D': 'Gathered into a single NULL group'}, 'D', 'Does it cause an error?'), ('Aggregate Coding: Find the department ID and average salary for departments with more than 3 employees.', 'SELECT department_id, AVG(salary) FROM employees GROUP BY department_id HAVING COUNT(*) > 3;', 'Easy', 'Coding', 'SELECT department_id, AVG(salary) AS avg_sal\nFROM employees\nGROUP BY department_id\nHAVING COUNT(*) > 3;', 'How do you round average salary to 2 decimal places?'), ('Aggregate Coding: Find the total revenue per year from an orders table.', 'SELECT EXTRACT(YEAR FROM order_date) AS order_year, SUM(total_amount) AS revenue FROM orders GROUP BY EXTRACT(YEAR FROM order_date);', 'Easy', 'Coding', 'SELECT EXTRACT(YEAR FROM order_date) AS order_year, SUM(total_amount) AS total_revenue\nFROM orders\nGROUP BY EXTRACT(YEAR FROM order_date)\nORDER BY order_year DESC;', 'How do you filter only years after 2020?'), ("Aggregate Coding: Count the number of active users per country where status is 'active'.", "SELECT country, COUNT(*) FROM users WHERE status = 'active' GROUP BY country;", 'Easy', 'Coding', "SELECT country, COUNT(*) AS active_count\nFROM users\nWHERE status = 'active'\nGROUP BY country;", 'Where is WHERE placed relative to GROUP BY?'), ("Aggregate Debugging: Query: 'SELECT department, name, MAX(salary) FROM employees GROUP BY department;' causes an error. Why?", "Column 'name' is in the SELECT clause but is neither in the GROUP BY clause nor wrapped in an aggregate function. Remove 'name' or add it to GROUP BY.", 'Intermediate', 'Debugging', '-- FIX:\nSELECT department, MAX(salary)\nFROM employees\nGROUP BY department;', 'What would name represent otherwise?'), ("Aggregate Debugging: Query: 'SELECT dept, AVG(salary) FROM emp WHERE AVG(salary) > 50000 GROUP BY dept;' fails. Why?", 'Aggregate function AVG(salary) cannot appear in the WHERE clause. Move condition to HAVING AVG(salary) > 50000.', 'Easy', 'Debugging', '-- FIX:\nSELECT dept, AVG(salary)\nFROM emp\nGROUP BY dept\nHAVING AVG(salary) > 50000;', 'Why does WHERE fail here?'), ('How do you find the second highest salary in an employees table?', 'SELECT MAX(salary) FROM employees WHERE salary < (SELECT MAX(salary) FROM employees);', 'Easy', 'Coding', 'SELECT MAX(salary) AS second_highest\nFROM employees\nWHERE salary < (\n  SELECT MAX(salary) FROM employees\n);', 'How do you find Nth highest salary?'), ('How do you find the Nth highest salary using LIMIT / OFFSET?', 'SELECT DISTINCT salary FROM employees ORDER BY salary DESC LIMIT 1 OFFSET N-1;', 'Intermediate', 'Coding', '-- For 3rd highest salary (N=3, offset=2):\nSELECT DISTINCT salary\nFROM employees\nORDER BY salary DESC\nLIMIT 1 OFFSET 2;', 'Why is DISTINCT required when finding Nth highest salary?'), ('Why is DISTINCT necessary when finding Nth highest salary?', 'Multiple employees may share the exact same top salaries (e.g. three employees earn 100k). Without DISTINCT, OFFSET 1 returns 100k again instead of the second unique salary.', 'Intermediate', 'Concept', '', 'How do you count duplicate rows in a table?'), ('How do you write a query to identify duplicate email addresses in a users table?', 'SELECT email, COUNT(*) FROM users GROUP BY email HAVING COUNT(*) > 1;', 'Easy', 'Coding', 'SELECT email, COUNT(*) AS occurrences\nFROM users\nGROUP BY email\nHAVING COUNT(*) > 1;', 'How do you delete the duplicates leaving only one?'), ('What does the MEDIAN function do and how is it calculated in standard SQL?', 'Median is the middle value in a sorted list. In PostgreSQL, calculate using PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY salary).', 'Advanced', 'Concept', 'SELECT PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY salary) FROM employees;', 'How does median differ from mean/average?'), ('What is the difference between Mean (AVG) and Median in statistics and SQL?', 'Mean is sensitive to extreme outliers (a CEO salary of $10M skews the average). Median represents the true 50th percentile midpoint, unaffected by outliers.', 'Intermediate', 'Comparison', '', 'What is variance and standard deviation in SQL?'), ('What do VAR_POP / STDDEV_POP functions calculate in SQL?', 'VAR_POP calculates population variance. STDDEV_POP (or STDDEV) calculates population standard deviation (dispersion from the mean).', 'Intermediate', 'Concept', 'SELECT STDDEV(score) FROM exam_results;', 'When are they used?'), ('Can CASE statements be placed inside aggregate functions?', "Yes! Conditional aggregation: SUM(CASE WHEN status = 'shipped' THEN 1 ELSE 0 END) counts specific status rows in a single query.", 'Intermediate', 'Practical', "SELECT department,\n  COUNT(*) AS total_employees,\n  SUM(CASE WHEN gender = 'F' THEN 1 ELSE 0 END) AS female_count,\n  SUM(CASE WHEN gender = 'M' THEN 1 ELSE 0 END) AS male_count\nFROM employees\nGROUP BY department;", 'Why is conditional aggregation powerful?'), ('Why is conditional aggregation (SUM(CASE WHEN ...)) powerful?', 'It allows pivoting row data into columnar summary statistics in a single table scan without needing multiple queries or joins.', 'Intermediate', 'Best Practice', '', 'What is query pivoting?'), ('Aggregate Coding: Count active vs inactive users in a single query using conditional aggregation.', 'SELECT SUM(CASE WHEN is_active THEN 1 ELSE 0 END) AS active, SUM(CASE WHEN NOT is_active THEN 1 ELSE 0 END) AS inactive FROM users;', 'Easy', 'Coding', "SELECT\n  COUNT(CASE WHEN status = 'active' THEN 1 END) AS active_users,\n  COUNT(CASE WHEN status = 'inactive' THEN 1 END) AS inactive_users\nFROM users;", 'How does COUNT(CASE WHEN...) work?'), ('Why does COUNT(CASE WHEN condition THEN 1 END) work without an ELSE branch?', 'When the condition is false, CASE defaults to NULL. COUNT ignores NULLs, so only matching rows are counted!', 'Intermediate', 'Concept', '', 'What is the FILTER clause in PostgreSQL aggregates?'), ('What is the FILTER (WHERE ...) clause in PostgreSQL and SQLite aggregate functions?', "An ANSI SQL feature allowing filtering specific aggregate expressions: COUNT(*) FILTER (WHERE status = 'active').", 'Intermediate', 'Practical', 'SELECT\n  department,\n  COUNT(*) AS total,\n  COUNT(*) FILTER (WHERE salary > 50000) AS high_earners\nFROM employees\nGROUP BY department;', 'Is FILTER cleaner than CASE?'), ('What does SUM(1) do in SQL?', 'SUM(1) counts the number of rows (equivalent to COUNT(*)).', 'Easy', 'Concept', 'SELECT department, SUM(1) FROM employees GROUP BY department;', 'Is COUNT(*) faster than SUM(1)?'), ('Is COUNT(*) faster than COUNT(1) in modern SQL optimizers?', 'They have identical performance in all modern RDBMS engines. The query optimizer treats COUNT(*), COUNT(1), and COUNT(0) identically.', 'Easy', 'Concept', '', 'What does COUNT(NULL) return in SQL?'), ("What does 'SELECT COUNT(NULL);' return in SQL?", 'It returns 0, because COUNT(expression) ignores NULL values.', 'Easy', 'Concept', 'SELECT COUNT(NULL); -- Returns 0', 'What does COUNT(*) return on an empty table?'), ('What is a JOIN in SQL and why is it used?', 'A JOIN is an SQL clause used to combine rows from two or more tables based on a related column between them (typically foreign key = primary key).', 'Easy', 'Concept', 'SELECT e.name, d.department_name\nFROM employees e\nINNER JOIN departments d ON e.dept_id = d.id;', 'What are the main types of joins?'), ('What are the 4 fundamental types of SQL joins?', '1. INNER JOIN (matches in both). 2. LEFT (OUTER) JOIN (all from left + matched right). 3. RIGHT (OUTER) JOIN (all from right + matched left). 4. FULL (OUTER) JOIN (all from both).', 'Easy', 'Concept', '', 'What is the difference between INNER JOIN and LEFT JOIN?'), ('What is the difference between INNER JOIN and LEFT JOIN?', 'INNER JOIN returns only rows where there is a matching value in BOTH tables. LEFT JOIN returns all rows from the left table, filling with NULL where no match exists on the right.', 'Easy', 'Comparison', '', 'What does a RIGHT JOIN do?'), ('What is a RIGHT JOIN?', 'RIGHT JOIN returns all rows from the right table, and matched rows from the left table. If there is no match on the left, NULL values are returned.', 'Easy', 'Concept', 'SELECT * FROM orders o RIGHT JOIN customers c ON o.customer_id = c.id;', 'Can every RIGHT JOIN be rewritten as a LEFT JOIN?'), ('Can every RIGHT JOIN be converted into a LEFT JOIN?', "Yes! Simply swap the table order: 'A RIGHT JOIN B' is identical to 'B LEFT JOIN A'. Most developers standardize on LEFT JOIN for readability.", 'Easy', 'Best Practice', '', 'What is a FULL OUTER JOIN?'), ('What is a FULL OUTER JOIN in SQL?', 'FULL OUTER JOIN returns all rows when there is a match in either left or right table. If there is no match, the missing side contains NULL.', 'Intermediate', 'Concept', 'SELECT * FROM t1 FULL OUTER JOIN t2 ON t1.id = t2.id;', 'Does MySQL support FULL OUTER JOIN natively?'), ('Does MySQL support FULL OUTER JOIN natively?', 'No. MySQL does not have a native FULL JOIN keyword. Emulate it using LEFT JOIN UNION RIGHT JOIN.', 'Intermediate', 'Practical', 'SELECT * FROM t1 LEFT JOIN t2 ON t1.id = t2.id\nUNION\nSELECT * FROM t1 RIGHT JOIN t2 ON t1.id = t2.id;', 'What is a CROSS JOIN?'), ('What is a CROSS JOIN (Cartesian Product) in SQL?', 'A CROSS JOIN produces the Cartesian product of two tables: every row of table A is paired with every row of table B (total rows = rows(A) * rows(B)).', 'Easy', 'Concept', 'SELECT * FROM sizes CROSS JOIN colors;', 'When is CROSS JOIN intentionally useful?'), ('When is a CROSS JOIN intentionally useful in business applications?', 'Generating combinations (e.g. all product sizes x all colors), or creating calendars/date matrices by cross-joining years with months.', 'Intermediate', 'Scenario', '', 'What is a Self Join in SQL?'), ('What is a Self Join and when is it used?', 'A Self Join is a regular join where a table is joined with itself using distinct aliases, commonly used for hierarchical data (e.g. employee and their manager).', 'Intermediate', 'Concept', 'SELECT e.name AS employee, m.name AS manager\nFROM employees e\nLEFT JOIN employees m ON e.manager_id = m.id;', 'Give an example of a Self Join query.'), ('Self Join Coding: Write a query to find all employees and the name of their manager.', 'SELECT e.name AS emp, m.name AS mgr FROM employees e LEFT JOIN employees m ON e.manager_id = m.id;', 'Easy', 'Coding', 'SELECT e.name AS employee_name, m.name AS manager_name\nFROM employees e\nLEFT JOIN employees m ON e.manager_id = m.id;', 'Why use LEFT JOIN instead of INNER JOIN for manager?'), ('Why should a Self Join for employee-manager use LEFT JOIN rather than INNER JOIN?', 'Because the top-level CEO/Founder has manager_id = NULL. An INNER JOIN would exclude the CEO completely from the results.', 'Easy', 'Scenario', '', 'What is a Natural Join in SQL?'), ('What is a NATURAL JOIN and why is it considered dangerous in production?', 'NATURAL JOIN joins tables automatically on all columns with identical names. If someone adds a column with the same name (like created_at) to both tables, the join condition silently breaks.', 'Intermediate', 'Comparison', '', 'What is the USING clause in SQL joins?'), ('What does the USING(column) clause do in SQL joins?', "Shorthand for ON when both tables share the exact same column name: 'JOIN orders USING (customer_id)' instead of 'ON a.customer_id = b.customer_id'.", 'Easy', 'Practical', 'SELECT * FROM customers JOIN orders USING (customer_id);', 'How does USING differ from ON?'), ('What happens if you join on a column where both tables have NULL values?', 'Rows with NULL do NOT match each other! In SQL, NULL = NULL evaluates to UNKNOWN. Rows with NULL keys are excluded from INNER JOIN.', 'Intermediate', 'Concept', '', 'How do you find rows in Table A that have NO match in Table B (Anti-Join)?'), ('How do you find records in Table A that do not exist in Table B using a LEFT JOIN?', 'Use LEFT JOIN with WHERE b.id IS NULL: SELECT a.* FROM a LEFT JOIN b ON a.id = b.a_id WHERE b.id IS NULL;.', 'Easy', 'Coding', 'SELECT c.id, c.name\nFROM customers c\nLEFT JOIN orders o ON c.id = o.customer_id\nWHERE o.id IS NULL; -- Customers with NO orders', 'What is an Anti-Join?'), ('What is an Anti-Join?', 'A relational algebra pattern that returns rows from one relation that have NO matching rows in another relation (achieved via LEFT JOIN IS NULL, NOT IN, or NOT EXISTS).', 'Intermediate', 'Concept', '', 'What is a Semi-Join in SQL?'), ('What is a Semi-Join?', 'A relational pattern that returns rows from table A where at least one match exists in table B, WITHOUT duplicating rows of table A (achieved via EXISTS or IN).', 'Intermediate', 'Concept', 'SELECT * FROM departments d\nWHERE EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id);', 'How does a Semi-Join differ from an INNER JOIN?'), ('How does a Semi-Join (EXISTS) differ from an INNER JOIN?', 'If a department has 100 employees, INNER JOIN duplicates the department row 100 times. A Semi-Join returns each matching department exactly ONCE.', 'Intermediate', 'Comparison', '', 'What is the difference between ON and WHERE in a LEFT JOIN?'), ('What is the critical difference between putting a filter condition in the ON clause vs the WHERE clause of a LEFT JOIN?', 'Conditions in ON filter the right table BEFORE joining (left table rows are still preserved). Conditions in WHERE filter the final result AFTER joining (drops left rows, converting LEFT JOIN into INNER JOIN!).', 'Advanced', 'Concept', "-- ON clause: Preserves all users, joins only active orders\nSELECT u.name, o.id\nFROM users u\nLEFT JOIN orders o ON u.id = o.user_id AND o.status = 'active';\n\n-- WHERE clause: Filters out users who have no active orders!\nSELECT u.name, o.id\nFROM users u\nLEFT JOIN orders o ON u.id = o.user_id\nWHERE o.status = 'active';", "Why does WHERE o.status = 'active' turn a LEFT JOIN into an INNER JOIN?"), ("Why does 'WHERE o.status = active' turn a LEFT JOIN into an INNER JOIN?", "Because rows without matching orders have o.status = NULL. The WHERE clause tests NULL = 'active' (false) and discards those rows.", 'Advanced', 'Scenario', '', 'Can you join more than two tables in a single query?'), ('How do you join three or more tables in SQL?', 'Chain JOIN clauses sequentially: SELECT * FROM orders o JOIN customers c ON o.c_id = c.id JOIN order_items oi ON o.id = oi.order_id JOIN products p ON oi.p_id = p.id;.', 'Easy', 'Practical', 'SELECT c.name, p.title\nFROM orders o\nJOIN customers c ON o.customer_id = c.id\nJOIN items i ON o.id = i.order_id\nJOIN products p ON i.product_id = p.id;', 'What is the difference between UNION and UNION ALL?'), ('What is the difference between UNION and UNION ALL in SQL?', 'UNION combines result sets from two queries and removes duplicate rows (requires an internal sort/hash). UNION ALL combines result sets WITHOUT removing duplicates (much faster).', 'Easy', 'Comparison', 'SELECT name FROM employees\nUNION ALL\nSELECT name FROM contractors;', 'Why is UNION ALL faster than UNION?'), ('Why is UNION ALL significantly faster than UNION?', 'UNION ALL does not check for or deduplicate records, avoiding expensive sorting or in-memory hash table deduplication.', 'Easy', 'Performance', '', 'What are the rules for combining queries with UNION?'), ('What are the two requirements for queries combined with UNION / UNION ALL?', '1. Each query must have the same number of columns in the SELECT list. 2. The corresponding columns must have compatible data types.', 'Easy', 'Concept', '', 'What does the INTERSECT operator do?'), ('What does the INTERSECT operator do in SQL?', 'INTERSECT returns only the rows that appear in BOTH query result sets (set intersection).', 'Easy', 'Concept', 'SELECT customer_id FROM online_orders\nINTERSECT\nSELECT customer_id FROM store_orders;', 'What does EXCEPT / MINUS operator do?'), ('What does the EXCEPT (or MINUS in Oracle) operator do?', 'EXCEPT returns rows from the first query that DO NOT appear in the second query (set difference).', 'Easy', 'Concept', 'SELECT product_id FROM all_products\nEXCEPT\nSELECT product_id FROM discontinued_products;', 'What is an Equi-Join vs Non-Equi Join?'), ('What is the difference between an Equi-Join and a Non-Equi Join?', "Equi-Join uses the equality operator '=' in the join condition. Non-Equi Join uses comparison operators (<, >, BETWEEN, !=) in the join condition.", 'Intermediate', 'Comparison', '-- Non-equi join:\nSELECT e.name, g.grade\nFROM employees e\nJOIN salary_grades g ON e.salary BETWEEN g.min_sal AND g.max_sal;', 'Give an example of a Non-Equi Join.'), ('Joins MCQ: Which join returns all rows from the left table and matching rows from the right table?', 'Option B is correct. LEFT OUTER JOIN preserves all left table records.', 'Easy', 'MCQ', '', {'A': 'INNER JOIN', 'B': 'LEFT JOIN', 'C': 'RIGHT JOIN', 'D': 'CROSS JOIN'}, 'B', 'What does INNER JOIN return?'), ("Joins MCQ: If Table A has 5 rows and Table B has 4 rows, how many rows does 'A CROSS JOIN B' return?", 'Option C is correct. 5 * 4 = 20 rows.', 'Easy', 'MCQ', '', {'A': '5', 'B': '9', 'C': '20', 'D': '1'}, 'C', 'What is this product called?'), ('Joins MCQ: What operator combines two query results and removes duplicate rows?', 'Option A is correct. UNION deduplicates; UNION ALL preserves duplicates.', 'Easy', 'MCQ', '', {'A': 'UNION', 'B': 'UNION ALL', 'C': 'JOIN', 'D': 'COMBINE'}, 'A', 'Which is faster?'), ('Joins MCQ: How do you identify records in Table A with no matches in Table B?', 'Option D is correct. LEFT JOIN Table B ON A.id = B.a_id WHERE B.id IS NULL.', 'Easy', 'MCQ', '', {'A': 'INNER JOIN WHERE B.id IS NULL', 'B': 'CROSS JOIN', 'C': 'FULL JOIN WHERE B.id = A.id', 'D': 'LEFT JOIN WHERE B.id IS NULL'}, 'D', 'What is this pattern called?'), ('Joins Coding: Find all customers who have never placed an order.', 'SELECT c.id, c.name FROM customers c LEFT JOIN orders o ON c.id = o.customer_id WHERE o.id IS NULL;', 'Easy', 'Coding', 'SELECT c.id, c.name\nFROM customers c\nLEFT JOIN orders o ON c.id = o.customer_id\nWHERE o.id IS NULL;', 'Can this be written with NOT EXISTS?'), ('Joins Coding: Write the previous query using NOT EXISTS.', 'SELECT * FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id);', 'Easy', 'Coding', 'SELECT c.id, c.name\nFROM customers c\nWHERE NOT EXISTS (\n  SELECT 1 FROM orders o WHERE o.customer_id = c.id\n);', 'Which is generally preferred by query optimizers?'), ("Joins Coding: Fetch all orders along with the customer's name and total order item count.", 'SELECT o.id, c.name, COUNT(oi.id) FROM orders o JOIN customers c ON o.customer_id = c.id JOIN order_items oi ON o.id = oi.order_id GROUP BY o.id, c.name;', 'Intermediate', 'Coding', 'SELECT o.id AS order_id, c.name AS customer_name, COUNT(oi.id) AS item_count\nFROM orders o\nJOIN customers c ON o.customer_id = c.id\nJOIN order_items oi ON o.id = oi.order_id\nGROUP BY o.id, c.name;', 'What if an order has 0 items?'), ('Joins Debugging: A developer wrote: SELECT * FROM users u LEFT JOIN orders o ON u.id = o.user_id WHERE o.amount > 100; but wanted all users. Why did users without orders disappear?', "The condition 'o.amount > 100' in WHERE eliminates rows where o.amount is NULL. Move the condition into the ON clause: ON u.id = o.user_id AND o.amount > 100.", 'Intermediate', 'Debugging', '-- FIX:\nSELECT * FROM users u\nLEFT JOIN orders o ON u.id = o.user_id AND o.amount > 100;', 'Why did the WHERE clause break the outer join?'), ('What is a Hash Join in query execution plans?', 'An execution algorithm where the database builds an in-memory hash table of the smaller table, then scans the larger table probing for matching hash keys. Ideal for large unsorted datasets.', 'Advanced', 'Architecture', '', 'What is a Nested Loop Join?'), ('What is a Nested Loop Join in database internals?', 'For each outer table row, the database scans the inner table (ideally using an index) for matches. Highly efficient when the outer table is small and inner table has an indexed join key.', 'Advanced', 'Architecture', '', 'What is a Merge Join (Sort-Merge Join)?'), ('What is a Merge Join (Sort-Merge Join)?', 'Both tables are sorted by the join key and scanned concurrently in lockstep. Highly efficient when input datasets are already sorted by indexes.', 'Advanced', 'Architecture', '', 'What is an alias clash in SQL joins?'), ('What is a column name ambiguity error in SQL joins?', "When both joined tables contain a column with the same name (like 'id'), selecting 'id' throws: 'Column id in field list is ambiguous'. Qualify with table alias: 'u.id'.", 'Easy', 'Debugging', '-- FIX:\nSELECT u.id AS user_id, o.id AS order_id\nFROM users u\nJOIN orders o ON u.id = o.user_id;', 'Why qualify columns?'), ('What does a CROSS APPLY / LATERAL JOIN do in SQL?', 'A LATERAL join (or CROSS APPLY in SQL Server) allows a subquery in the FROM/JOIN clause to reference columns from preceding tables in the join sequence.', 'Advanced', 'Concept', 'SELECT c.name, o.*\nFROM customers c\nCROSS JOIN LATERAL (\n  SELECT * FROM orders WHERE customer_id = c.id ORDER BY date DESC LIMIT 3\n) o;', 'When is LATERAL join useful?'), ('How do you find the top 3 most recent orders for EVERY customer?', 'Use a LATERAL JOIN (or CROSS APPLY): join each customer with a subquery selecting their 3 most recent orders.', 'Advanced', 'Coding', 'SELECT c.name, recent_orders.id, recent_orders.order_date\nFROM customers c\nCROSS JOIN LATERAL (\n  SELECT id, order_date FROM orders\n  WHERE customer_id = c.id\n  ORDER BY order_date DESC LIMIT 3\n) AS recent_orders;', 'What is the equivalent in window functions?'), ('What is an inner join on multiple conditions?', 'JOIN t2 ON t1.id = t2.t1_id AND t1.tenant_id = t2.tenant_id (essential for multi-tenant database designs).', 'Intermediate', 'Practical', 'JOIN invoices i ON c.id = i.customer_id AND c.country = i.country', 'Why is multi-column join condition used?'), ('What happens if you omit the ON clause in an INNER JOIN?', 'In MySQL, INNER JOIN without ON acts as a CROSS JOIN, generating a Cartesian product. In strict SQL dialects like PostgreSQL, omitting ON produces a syntax error.', 'Intermediate', 'Concept', '', 'What is self join with inequality?'), ('Self Join Coding: Find all pairs of employees who work in the same department without pairing an employee with themselves.', 'SELECT e1.name, e2.name, e1.dept_id FROM employees e1 JOIN employees e2 ON e1.dept_id = e2.dept_id AND e1.id < e2.id;', 'Intermediate', 'Coding', 'SELECT e1.name AS emp1, e2.name AS emp2, e1.department_id\nFROM employees e1\nJOIN employees e2 ON e1.department_id = e2.department_id AND e1.id < e2.id;', 'Why use e1.id < e2.id instead of != ?'), ("Why is 'e1.id < e2.id' used instead of 'e1.id != e2.id' in pair matching?", "'!=' produces duplicate reverse pairs (Alice & Bob, and Bob & Alice). '<' ensures each pair is listed exactly once and prevents self-matching.", 'Intermediate', 'Concept', '', 'What is a Star Schema in data warehousing?'), ('What is a Star Schema in database design?', 'A design where a central Fact table containing quantitative metrics is directly connected to multiple surrounding Dimension tables via foreign keys.', 'Intermediate', 'Architecture', '', 'What is a Snowflake Schema?'), ('What is the difference between a Star Schema and a Snowflake Schema?', 'In a Star Schema, dimension tables are denormalized. In a Snowflake Schema, dimension tables are normalized into further sub-dimension tables resembling a snowflake.', 'Intermediate', 'Comparison', '', 'What is a Fact table vs Dimension table?'), ('What is the difference between a Fact Table and a Dimension Table?', 'Fact table: stores numerical business measurements and transactions (sales amount, quantity, timestamps). Dimension table: stores descriptive context attributes (customer name, product category, store location).', 'Intermediate', 'Comparison', '', 'What is data federation in SQL?'), ('What is a Foreign Data Wrapper (FDW) in PostgreSQL?', 'A feature allowing PostgreSQL to query remote tables in other databases (MySQL, Redis, MongoDB, remote Postgres) using standard SQL queries as if they were local tables.', 'Advanced', 'Architecture', '', 'What is DBLink in MySQL/Oracle?'), ('What is a Database Link (DBLink)?', 'A database connection definition enabling queries on a local database to access objects on a remote database server.', 'Intermediate', 'Concept', '', 'How does a database handle joining tables with different collations?'), ("What causes 'Illegal mix of collations' error in MySQL joins?", 'Joining string columns that have different character sets or collations (e.g. utf8mb4_general_ci vs utf8mb4_unicode_ci). Fix by specifying COLLATE in the join condition.', 'Intermediate', 'Debugging', 'ON a.code COLLATE utf8mb4_unicode_ci = b.code', 'How do you fix collation mismatch?'), ('What is join cardinality?', 'The numerical relationship between records in joined tables: 1-to-1, 1-to-Many, or Many-to-Many.', 'Easy', 'Concept', '', 'How is a Many-to-Many relationship implemented in SQL?'), ('How do you model a Many-to-Many relationship between Students and Courses?', 'Create a Junction / Bridge / Pivot table (student_courses) containing foreign keys referencing both primary keys (student_id, course_id).', 'Easy', 'Concept', 'CREATE TABLE student_courses (\n  student_id INT REFERENCES students(id),\n  course_id INT REFERENCES courses(id),\n  PRIMARY KEY (student_id, course_id)\n);', 'What is the primary key of a junction table?'), ('What is an outer join on NULLable foreign keys?', 'When foreign keys can be NULL, an INNER JOIN silently discards records where FK is NULL. Always use LEFT JOIN if unassigned records must be preserved.', 'Easy', 'Best Practice', '', 'Why should join conditions only contain relationship predicates?'), ('Why should business filters be in WHERE rather than ON in an INNER JOIN?', 'While ON and WHERE produce identical results in INNER JOIN, placing join keys in ON and business filters in WHERE makes SQL queries much cleaner to read and maintain.', 'Easy', 'Best Practice', '', 'What is an implicit join vs explicit join?'), ('What is the difference between an Implicit Join and an Explicit Join?', "Implicit: 'FROM tableA, tableB WHERE tableA.id = tableB.id' (old SQL-89 syntax). Explicit: 'FROM tableA JOIN tableB ON ...' (SQL-92 syntax). Always use Explicit Joins.", 'Easy', 'Comparison', '-- Implicit (AVOID):\nSELECT * FROM a, b WHERE a.id = b.id;\n-- Explicit (RECOMMENDED):\nSELECT * FROM a JOIN b ON a.id = b.id;', 'Why is explicit join preferred?'), ('Why is explicit JOIN syntax strongly preferred over implicit comma joins?', 'Explicit joins separate join logic from filtering logic, prevent accidental Cartesian products from forgotten WHERE conditions, and support all outer join types cleanly.', 'Easy', 'Best Practice', '', 'Can you join on expressions rather than direct columns?'), ('Can a join condition use functions and expressions?', 'Yes: ON DATE(a.created_at) = DATE(b.created_at). However, wrapping indexed columns in functions prevents index usage, causing slow full table scans.', 'Intermediate', 'Performance', '', 'How do you optimize an expression join?'), ('How do you optimize joins on expressions to maintain index speed?', 'Use generated columns (virtual/stored) with an index on the generated column, or store pre-calculated values directly.', 'Advanced', 'Performance', '', 'What is join elimination in SQL query optimizers?'), ('What is Join Elimination in database query optimizers?', "An optimization where the database detects that a joined table's columns are never selected and its foreign key constraint guarantees matching rows, removing the join entirely from execution!", 'Advanced', 'Architecture', '', 'When does join elimination occur?'), ('What is a Subquery in SQL?', 'A Subquery (inner query / nested query) is a SELECT query nested inside another SQL statement (SELECT, INSERT, UPDATE, or DELETE).', 'Easy', 'Concept', 'SELECT * FROM emp WHERE salary > (SELECT AVG(salary) FROM emp);', 'What are the three types of subqueries by location?'), ('Where can subqueries be placed in an SQL statement?', 'In the WHERE clause (filtering), FROM clause (derived table), and SELECT clause (scalar projection).', 'Easy', 'Concept', '', 'What is a Scalar Subquery?'), ('What is a Scalar Subquery?', 'A subquery that returns exactly ONE row and ONE column (a single value). It can be used anywhere a scalar literal value is expected.', 'Easy', 'Concept', 'SELECT name, (SELECT MAX(price) FROM products) AS max_p FROM products;', 'What happens if a scalar subquery returns multiple rows?'), ('What error occurs if a scalar subquery returns more than one row?', "The database throws a runtime error: 'Subquery returned more than 1 value' / 'scalar subquery produced more than one element'.", 'Easy', 'Debugging', '', 'What is a Correlated Subquery?'), ('What is a Correlated Subquery and how does it differ from a non-correlated subquery?', 'A non-correlated subquery executes once independently of the outer query. A Correlated Subquery references columns from the outer query and executes once for EVERY candidate row processed by the outer query.', 'Intermediate', 'Comparison', 'SELECT e.name, e.salary\nFROM employees e\nWHERE e.salary > (\n  SELECT AVG(salary) FROM employees WHERE department_id = e.department_id\n);', 'Why can correlated subqueries be slow on large tables?'), ('Why can correlated subqueries cause performance bottlenecks?', 'Because they execute row-by-row (O(N) executions). If the outer table has 100,000 rows, the subquery may execute 100,000 times unless optimized or rewritten with a JOIN / Window function.', 'Intermediate', 'Performance', '', 'What is the EXISTS operator in SQL?'), ('What does the EXISTS operator do and how does it optimize execution?', 'EXISTS tests for the existence of rows in a subquery. It returns TRUE as soon as the first matching row is found and stops scanning immediately (short-circuit evaluation).', 'Easy', 'Concept', 'SELECT * FROM customers c WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id);', "Why is 'SELECT 1' standard in EXISTS subqueries?"), ("Why do developers write 'SELECT 1' inside an EXISTS subquery?", 'Because EXISTS only cares whether any matching row exists, not what columns are selected. Writing SELECT 1 makes intent explicit and avoids column overhead.', 'Easy', 'Best Practice', 'WHERE EXISTS (SELECT 1 FROM ...)', 'What is the difference between IN and EXISTS?'), ('What is the difference between IN and EXISTS?', 'IN evaluates all values returned by the subquery into a set and checks membership. EXISTS evaluates conditionally row-by-row and short-circuits. EXISTS handles NULLs safely, whereas NOT IN fails if NULLs exist.', 'Intermediate', 'Comparison', '', 'When is EXISTS faster?'), ('What is a Common Table Expression (CTE) and what keyword defines it?', 'A CTE is a temporary named result set defined within a single SQL statement using the WITH keyword: WITH cte_name AS (SELECT ...).', 'Easy', 'Concept', 'WITH HighEarners AS (\n  SELECT * FROM employees WHERE salary > 100000\n)\nSELECT department_id, COUNT(*) FROM HighEarners GROUP BY department_id;', 'What are the benefits of CTEs over subqueries?'), ('What are the advantages of Common Table Expressions (CTEs)?', '1. Greatly improves code readability and modularity. 2. Can be referenced multiple times within the same query. 3. Enables Recursive Queries for hierarchies.', 'Easy', 'Concept', '', 'What is a Recursive CTE in SQL?'), ('What is a Recursive CTE and when is it used?', 'A CTE that references itself to traverse hierarchical or tree-structured data (organizational charts, bill-of-materials, graph paths).', 'Advanced', 'Concept', 'WITH RECURSIVE OrgChart AS (\n  SELECT id, name, manager_id, 1 AS level FROM employees WHERE manager_id IS NULL\n  UNION ALL\n  SELECT e.id, e.name, e.manager_id, o.level + 1\n  FROM employees e JOIN OrgChart o ON e.manager_id = o.id\n)\nSELECT * FROM OrgChart;', 'What are the two parts of a recursive CTE?'), ('What are the two parts of a Recursive CTE?', '1. Anchor Member (base query, executes once). 2. Recursive Member (query that joins the CTE with the table, executing iteratively until no new rows are returned).', 'Advanced', 'Concept', '', 'What happens if a recursive CTE has an infinite loop?'), ('How do databases prevent infinite loops in recursive CTEs?', 'Most engines have safety recursion limits (e.g. MAXRECURSION 100 in SQL Server, max_statement_time in MySQL) and throw an error if exceeded.', 'Intermediate', 'Concept', '', 'What are Window Functions in SQL?'), ('What are Window Functions (Analytic Functions) in SQL?', "Window functions perform calculations across a set of table rows related to the current row (a 'window'), WITHOUT collapsing rows like GROUP BY does.", 'Intermediate', 'Concept', 'SELECT name, department, salary,\n  AVG(salary) OVER(PARTITION BY department) AS dept_avg\nFROM employees;', 'What is the OVER() clause in window functions?'), ('What does the OVER() clause specify in window functions?', 'It defines the partition (PARTITION BY) and ordering (ORDER BY) of the row window over which the function operates.', 'Easy', 'Concept', 'OVER (PARTITION BY department_id ORDER BY salary DESC)', 'What is the difference between ROW_NUMBER(), RANK(), and DENSE_RANK()?'), ('What is the difference between ROW_NUMBER(), RANK(), and DENSE_RANK()?', 'ROW_NUMBER(): Assigns unique sequential integers (1, 2, 3, 4) regardless of ties. RANK(): Assigns same rank to ties and skips subsequent ranks (1, 2, 2, 4). DENSE_RANK(): Assigns same rank to ties WITHOUT skipping (1, 2, 2, 3).', 'Intermediate', 'Comparison', '-- If salaries are: 100, 90, 90, 80\n-- ROW_NUMBER: 1, 2, 3, 4\n-- RANK:       1, 2, 2, 4\n-- DENSE_RANK: 1, 2, 2, 3', 'Which function should be used to find top 3 distinct salaries?'), ('Which window function should you use to find the top 3 highest unique salaries?', 'DENSE_RANK(), because it does not skip ranks when duplicate salaries tie.', 'Intermediate', 'Best Practice', '', 'Why does DENSE_RANK not skip?'), ('Window Functions Coding: Find the top 2 highest paid employees in every department.', 'WITH ranked AS (SELECT *, DENSE_RANK() OVER(PARTITION BY department_id ORDER BY salary DESC) as r FROM employees) SELECT * FROM ranked WHERE r <= 2;', 'Intermediate', 'Coding', 'WITH RankedEmployees AS (\n  SELECT id, name, department_id, salary,\n    DENSE_RANK() OVER (PARTITION BY department_id ORDER BY salary DESC) AS sal_rank\n  FROM employees\n)\nSELECT * FROM RankedEmployees\nWHERE sal_rank <= 2;', 'Why must window function filtering be wrapped in a CTE or subquery?'), ("Why can't you use window functions directly inside a WHERE clause?", 'Because Window functions are computed in step 6 of query execution, AFTER the WHERE clause (step 2) has already executed. Wrap in a CTE or subquery.', 'Intermediate', 'Concept', '-- WRONG: WHERE ROW_NUMBER() OVER (...) <= 2\n-- CORRECT: Wrap in CTE then filter in outer query', 'What does LEAD() function do?'), ('What does the LEAD(column, [offset], [default]) window function do?', "LEAD accesses data from a subsequent (following) row at a specified offset without needing a self-join (e.g. comparing this month's revenue with next month).", 'Intermediate', 'Concept', 'SELECT month, revenue,\n  LEAD(revenue, 1) OVER (ORDER BY month) AS next_month_revenue\nFROM monthly_sales;', 'What does LAG() function do?'), ('What does the LAG(column, [offset], [default]) window function do?', 'LAG accesses data from a preceding (previous) row at a specified offset (e.g. calculating day-over-day growth: today_sales - LAG(today_sales, 1)).', 'Intermediate', 'Concept', 'SELECT date, sales,\n  sales - LAG(sales, 1) OVER (ORDER BY date) AS daily_growth\nFROM daily_sales;', 'How do you calculate year-over-year growth with LAG?'), ('Window Coding: Calculate month-over-month revenue growth percentage.', 'SELECT month, revenue, ROUND(100.0 * (revenue - LAG(revenue) OVER(ORDER BY month)) / LAG(revenue) OVER(ORDER BY month), 2) AS growth_pct FROM sales;', 'Intermediate', 'Coding', 'SELECT month, revenue,\n  ROUND(\n    100.0 * (revenue - LAG(revenue) OVER (ORDER BY month)) /\n    LAG(revenue) OVER (ORDER BY month),\n    2\n  ) AS mom_growth_pct\nFROM monthly_revenue;', 'What does FIRST_VALUE() and LAST_VALUE() do?'), ('What do FIRST_VALUE() and LAST_VALUE() window functions do?', 'FIRST_VALUE returns the first value in an ordered partition. LAST_VALUE returns the last value in the window frame.', 'Intermediate', 'Concept', 'FIRST_VALUE(salary) OVER (PARTITION BY dept ORDER BY salary DESC)', 'What is window frame (ROWS BETWEEN)?'), ("What does 'ROWS BETWEEN 2 PRECEDING AND CURRENT ROW' mean in window frames?", 'It defines a sliding calculation window including the current row and the two rows immediately before it (used for 3-day moving averages).', 'Advanced', 'Concept', 'AVG(sales) OVER (\n  ORDER BY date\n  ROWS BETWEEN 2 PRECEDING AND CURRENT ROW\n) AS three_day_moving_avg', 'Give an example of a moving average query.'), ('Window Coding: Write a query to compute a 7-day moving average of daily active users.', 'SELECT date, AVG(dau) OVER (ORDER BY date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS moving_avg_7d FROM daily_metrics;', 'Intermediate', 'Coding', 'SELECT date, active_users,\n  AVG(active_users) OVER (\n    ORDER BY date\n    ROWS BETWEEN 6 PRECEDING AND CURRENT ROW\n  ) AS moving_avg_7d\nFROM daily_metrics;', 'What is NTILE(n) window function?'), ('What does the NTILE(n) window function do in SQL?', 'NTILE divides an ordered partition into n approximately equal groups (buckets), assigning a bucket number from 1 to n (e.g. NTILE(4) creates quartiles).', 'Intermediate', 'Concept', 'SELECT name, salary, NTILE(4) OVER (ORDER BY salary DESC) AS quartile FROM employees;', 'When is NTILE useful?'), ('What is the difference between ROWS and RANGE in window frames?', 'ROWS treats duplicates as individual distinct physical lines. RANGE treats rows with identical ORDER BY values as a single peer group logical range.', 'Advanced', 'Comparison', '', 'What is the ANY / SOME operator in SQL subqueries?'), ("What does the '> ANY (subquery)' condition mean in SQL?", 'It evaluates to TRUE if the value is greater than AT LEAST ONE value returned by the subquery (equivalent to > MIN(subquery)).', 'Intermediate', 'Concept', 'WHERE salary > ANY (SELECT salary FROM employees WHERE dept_id = 3)', 'What does the ALL operator do?'), ("What does the '> ALL (subquery)' condition mean in SQL?", 'It evaluates to TRUE if the value is greater than EVERY single value returned by the subquery (equivalent to > MAX(subquery)).', 'Intermediate', 'Concept', 'WHERE salary > ALL (SELECT salary FROM employees WHERE dept_id = 3)', 'What is a derived table?'), ('What is a Derived Table in SQL?', 'An unnamed subquery in the FROM clause that creates a temporary virtual table for the outer query; it MUST be given an alias in most RDBMS.', 'Easy', 'Concept', 'SELECT * FROM (SELECT id, name FROM users) AS u;', 'Why do derived tables require aliases in MySQL?'), ('Why does MySQL throw an error if a subquery in FROM has no alias?', "MySQL syntax strictly requires: 'Every derived table must have its own alias' so columns can be unambiguously referenced.", 'Easy', 'Debugging', '-- WRONG: SELECT * FROM (SELECT 1);\n-- CORRECT: SELECT * FROM (SELECT 1) AS t;', 'Subqueries MCQ: What is the difference between RANK() and DENSE_RANK() when ties occur?'), ('Subqueries MCQ: If scores are 90, 90, 80, what ranks does DENSE_RANK() assign?', 'Option B is correct. 1, 1, 2 (no ranks skipped).', 'Easy', 'MCQ', '', {'A': '1, 2, 3', 'B': '1, 1, 2', 'C': '1, 1, 3', 'D': '1, 2, 2'}, 'B', 'What would RANK() assign?'), ('Subqueries MCQ: Which window function retrieves the value from the preceding row without a self-join?', 'Option A is correct. LAG() accesses prior rows.', 'Easy', 'MCQ', '', {'A': 'LAG()', 'B': 'LEAD()', 'C': 'PREV()', 'D': 'PRIOR()'}, 'A', 'What accesses subsequent rows?'), ('Subqueries MCQ: What keyword introduces a Common Table Expression?', 'Option C is correct. WITH introduces CTEs.', 'Easy', 'MCQ', '', {'A': 'AS', 'B': 'CTE', 'C': 'WITH', 'D': 'DECLARE'}, 'C', 'Can multiple CTEs be defined with one WITH?'), ('Subqueries MCQ: Which operator checks if a subquery returns ANY rows with short-circuit evaluation?', 'Option D is correct. EXISTS short-circuits on first match.', 'Easy', 'MCQ', '', {'A': 'IN', 'B': 'ANY', 'C': 'ALL', 'D': 'EXISTS'}, 'D', 'What does it return if match found?'), ('Subqueries Coding: Write a query to find all employees whose salary is above the average salary of their own department.', 'SELECT * FROM employees e WHERE salary > (SELECT AVG(salary) FROM employees WHERE department_id = e.department_id);', 'Intermediate', 'Coding', 'SELECT e.id, e.name, e.salary, e.department_id\nFROM employees e\nWHERE e.salary > (\n  SELECT AVG(salary)\n  FROM employees\n  WHERE department_id = e.department_id\n);', 'How can this be written with a window function?'), ('Window Coding: Write the same above-average query using a window function in a CTE.', 'WITH dept_avgs AS (SELECT *, AVG(salary) OVER(PARTITION BY department_id) as avg_sal FROM employees) SELECT * FROM dept_avgs WHERE salary > avg_sal;', 'Intermediate', 'Coding', 'WITH DeptAverages AS (\n  SELECT id, name, department_id, salary,\n    AVG(salary) OVER (PARTITION BY department_id) AS dept_avg\n  FROM employees\n)\nSELECT id, name, department_id, salary, dept_avg\nFROM DeptAverages\nWHERE salary > dept_avg;', 'Why is the window function approach faster?'), ("Subqueries Debugging: Query: 'SELECT name FROM users WHERE id NOT IN (SELECT manager_id FROM employees);' returns 0 rows. Why?", "If any employee has manager_id = NULL, NOT IN returns an empty set. Fix by adding 'WHERE manager_id IS NOT NULL' or using NOT EXISTS.", 'Intermediate', 'Debugging', '-- FIX:\nSELECT name FROM users\nWHERE id NOT IN (\n  SELECT manager_id FROM employees WHERE manager_id IS NOT NULL\n);', 'Why does NULL break NOT IN?'), ('What is the Cumulative Distribution function CUME_DIST()?', 'CUME_DIST calculates the relative rank of a value in a partition (percentage of rows with values <= current row). Range is 0 < CUME_DIST <= 1.', 'Advanced', 'Concept', 'SELECT name, salary, CUME_DIST() OVER (ORDER BY salary) FROM emp;', 'What is PERCENT_RANK()?'), ('What does PERCENT_RANK() calculate in SQL?', 'PERCENT_RANK evaluates relative rank as a percentage from 0.0 to 1.0: (rank - 1) / (total_rows - 1).', 'Advanced', 'Concept', 'SELECT name, salary, PERCENT_RANK() OVER (ORDER BY salary) FROM emp;', 'How does it differ from CUME_DIST?'), ('What is running total in SQL and how do you calculate it?', 'A running total accumulates values row-by-row. Calculate using: SUM(amount) OVER (ORDER BY transaction_date).', 'Easy', 'Coding', 'SELECT date, amount,\n  SUM(amount) OVER (ORDER BY date) AS running_total\nFROM transactions;', 'How do you calculate running total per customer?'), ('Window Coding: Calculate a running total of deposits partitioned by customer account.', 'SELECT account_id, date, amount, SUM(amount) OVER (PARTITION BY account_id ORDER BY date) AS balance FROM transactions;', 'Easy', 'Coding', 'SELECT account_id, transaction_date, amount,\n  SUM(amount) OVER (\n    PARTITION BY account_id\n    ORDER BY transaction_date\n  ) AS account_running_balance\nFROM transactions;', 'What happens if ORDER BY is omitted in the OVER clause?'), ("What happens if ORDER BY is omitted from 'SUM(amount) OVER ()'?", 'Without ORDER BY, the window frame spans the ENTIRE partition, calculating the overall grand total rather than a progressive running sum.', 'Intermediate', 'Concept', 'SELECT amount, SUM(amount) OVER () AS grand_total FROM sales;', 'Why does adding ORDER BY change it to a running sum?'), ('Why does adding ORDER BY change SUM() OVER() into a running sum?', "By default, adding ORDER BY implies the window frame 'RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW'.", 'Advanced', 'Concept', '', 'What is the QUALIFY clause in Snowflake/BigQuery?'), ('What does the QUALIFY clause do in modern SQL dialects (Snowflake, BigQuery, Databricks)?', 'QUALIFY filters the results of window functions directly at the end of the query without requiring an enclosing CTE or subquery.', 'Intermediate', 'Practical', 'SELECT name, department, salary\nFROM employees\nQUALIFY ROW_NUMBER() OVER (PARTITION BY department ORDER BY salary DESC) = 1;', 'Is QUALIFY standard ANSI SQL?'), ('What is an inline view vs a stored view?', 'Inline view: a subquery in the FROM clause of a single statement. Stored view: a named query saved in the database catalog (CREATE VIEW view_name AS ...).', 'Easy', 'Comparison', '', 'What is a Materialized View?'), ('What is a Materialized View and how does it differ from a standard View?', 'A standard View is a saved query run dynamically on demand. A Materialized View executes once and physically saves the resulting data to disk, updated via REFRESH MATERIALIZED VIEW.', 'Intermediate', 'Comparison', 'CREATE MATERIALIZED VIEW monthly_sales_mv AS SELECT ...;', 'When should you use a Materialized View?'), ('When should Materialized Views be used?', 'For expensive, slow analytical aggregation queries on large tables where real-time freshness is not required and data can be refreshed periodically.', 'Intermediate', 'Architecture', '', 'What is the WITH CHECK OPTION on updatable SQL views?'), ("What does 'WITH CHECK OPTION' do on an updatable View?", "It prevents any INSERT or UPDATE through the view from setting values that would violate the view's WHERE condition and cause the row to disappear from the view.", 'Intermediate', 'Concept', 'CREATE VIEW v_active AS SELECT * FROM users WHERE active = true WITH CHECK OPTION;', 'What happens if you try to insert active=false?'), ('What is Database Normalization and why is it performed?', 'Normalization is the systematic process of organizing database tables to eliminate data redundancy, prevent update anomalies, and ensure data integrity.', 'Easy', 'Concept', '', 'What are the three main types of update anomalies?'), ('What are Insertion, Update, and Deletion Anomalies?', 'Insertion Anomaly: Cannot record data without adding unrelated data. Update Anomaly: Inconsistent data when editing duplicate values in multiple places. Deletion Anomaly: Unintentionally losing other data when deleting a record.', 'Intermediate', 'Concept', '', 'What is First Normal Form (1NF)?'), ('What are the requirements for First Normal Form (1NF)?', '1. Each column must hold atomic (indivisible) values (no arrays or comma-separated lists). 2. Each record must have a unique identifier (Primary Key). 3. No repeating groups of columns.', 'Easy', 'Concept', "-- Violates 1NF: phone = '123-456, 789-012'\n-- 1NF Compliant: separate rows for each phone", 'What is Second Normal Form (2NF)?'), ('What are the requirements for Second Normal Form (2NF)?', '1. Table must be in 1NF. 2. All non-key attributes must be fully functionally dependent on the ENTIRE primary key (no partial dependencies on part of a composite primary key).', 'Intermediate', 'Concept', '', 'What is Third Normal Form (3NF)?'), ('What are the requirements for Third Normal Form (3NF)?', '1. Table must be in 2NF. 2. No transitive dependencies: non-key attributes must NOT depend on other non-key attributes (every column must depend only on the primary key).', 'Intermediate', 'Concept', '-- Violates 3NF: emp_id -> dept_id -> dept_name (dept_name depends on dept_id, not emp_id)', 'What is BCNF (Boyce-Codd Normal Form)?'), ('What is Boyce-Codd Normal Form (BCNF)?', 'A stricter version of 3NF where every functional determinant must be a candidate key (for every X -> Y, X must be a super key).', 'Advanced', 'Concept', '', 'What is Denormalization and when is it justified?'), ('What is Denormalization and why is it used in production systems?', 'Deliberately introducing controlled redundancy into a normalized schema to reduce expensive joins and improve read performance in read-heavy applications.', 'Intermediate', 'Concept', '', 'What are the risks of Denormalization?'), ('What are the major trade-offs of Denormalization?', 'Faster read queries, but slower writes, increased storage consumption, and higher risk of data inconsistency when updating duplicate fields.', 'Intermediate', 'Comparison', '', 'What is an Index in SQL and how does it work?'), ('What is a Database Index and what data structure is most commonly used?', 'An index is a lookup data structure that allows the database engine to find specific rows in O(log N) time rather than scanning every row (O(N) full table scan). Most commonly implemented as B-Trees.', 'Easy', 'Concept', 'CREATE INDEX idx_users_email ON users(email);', 'What is the trade-off of adding indexes?'), ('What are the drawbacks and costs of adding indexes?', 'Indexes consume additional disk space and slow down write operations (INSERT, UPDATE, DELETE) because every index must be updated on every write.', 'Easy', 'Best Practice', '', 'What is a Clustered Index vs a Non-Clustered Index?'), ('What is the difference between a Clustered Index and a Non-Clustered (Secondary) Index?', 'Clustered Index: Determines the physical storage order of data rows on disk (only ONE clustered index per table, typically the Primary Key). Non-Clustered Index: A separate structure with pointers/keys pointing back to the physical data rows.', 'Intermediate', 'Comparison', '', 'Why can a table have only ONE Clustered Index?'), ('Why can a table have only one clustered index?', 'Because physical data rows can only be sorted and stored on disk in one single order.', 'Easy', 'Concept', '', 'What is a Composite (Compound) Index?'), ('What is a Composite Index in SQL?', 'An index created on two or more columns together: CREATE INDEX idx_emp_dept_sal ON employees(department_id, salary);.', 'Easy', 'Concept', 'CREATE INDEX idx_name ON users(last_name, first_name);', 'What is the Leftmost Prefix Rule in composite indexes?'), ('What is the Leftmost Prefix Rule in composite indexes?', 'A composite index on (A, B, C) can speed up queries filtering on (A), (A, B), or (A, B, C), but CANNOT be used if query filters only on (B) or (C) without (A).', 'Intermediate', 'Concept', "-- Index: (last_name, first_name)\n-- USES index: WHERE last_name = 'Smith'\n-- DOES NOT use index: WHERE first_name = 'John'", 'Why does the order of columns in a composite index matter?'), ('Why does column order in a composite index matter?', 'B-Trees sort data first by the first column, then by the second within matching values of the first. Searching by the second column alone requires a full index scan.', 'Intermediate', 'Concept', '', 'What is a Covering Index?'), ('What is a Covering Index in SQL?', 'An index that contains ALL the columns requested by a query (both WHERE and SELECT columns), allowing the database to return results purely from index memory without touching disk table pages.', 'Advanced', 'Performance', 'CREATE INDEX idx_covering ON users(email, first_name, last_name);', 'What is Index Selectivity?'), ('What is Index Selectivity and why does it determine whether an index is used?', 'Selectivity is the ratio of distinct values to total rows. High selectivity (unique email, 99% distinct) makes indexes extremely efficient. Low selectivity (gender, boolean status) causes optimizer to prefer full table scan.', 'Intermediate', 'Concept', '', 'What is the EXPLAIN / EXPLAIN ANALYZE command?'), ('What does EXPLAIN (or EXPLAIN ANALYZE) do in SQL?', 'EXPLAIN displays the execution plan chosen by the query optimizer (showing table scans, index lookups, join types, and estimated row costs). ANALYZE actually executes the query and shows real runtime stats.', 'Easy', 'Practical', "EXPLAIN ANALYZE SELECT * FROM users WHERE email = 'test@example.com';", 'What is a Full Table Scan (Seq Scan)?'), ('What is a Full Table Scan (Sequential Scan)?', 'The database reads every single data page on disk from start to finish. Essential for small tables or when fetching >20-30% of all rows, but disastrous for large tables with targeted lookups.', 'Easy', 'Concept', 'type: ALL (MySQL) / Seq Scan (PostgreSQL)', 'Name three common causes of index invalidation in queries.'), ('What query patterns prevent an index from being used (SARGability)?', "1. Wrapping column in a function: WHERE YEAR(created_at) = 2026. 2. Leading wildcard: WHERE name LIKE '%son'. 3. Implicit type conversion: WHERE varchar_col = 123. 4. Doing arithmetic on column: WHERE age + 1 > 18.", 'Intermediate', 'Performance', "-- BAD: WHERE LOWER(email) = 'a@b.com'\n-- GOOD: WHERE email = 'a@b.com' (with case-insensitive collation)", "How do you rewrite 'WHERE YEAR(created_at) = 2026' to use an index?"), ("How do you rewrite 'WHERE YEAR(created_at) = 2026' to allow index usage?", "Use a date range: WHERE created_at >= '2026-01-01' AND created_at < '2027-01-01'.", 'Intermediate', 'Coding', "-- Index-friendly range query:\nWHERE created_at >= '2026-01-01 00:00:00'\n  AND created_at < '2027-01-01 00:00:00'", 'What is a Partial / Filtered Index?'), ('What is a Partial Index (Filtered Index)?', 'An index built over a subset of rows satisfying a WHERE condition (e.g. index only active users), saving disk space and speeding up targeted queries.', 'Intermediate', 'Concept', 'CREATE INDEX idx_active_users ON users(email) WHERE is_active = true;', 'What are ACID properties in database transactions?'), ('What do the letters in ACID stand for?', 'Atomicity, Consistency, Isolation, and Durability. They guarantee database reliability in the face of errors and concurrent access.', 'Easy', 'Concept', '', 'Explain Atomicity in ACID.'), ('What does Atomicity mean in ACID?', "'All or Nothing'. All operations within a transaction must either complete successfully together, or the entire transaction is rolled back leaving the database unchanged.", 'Easy', 'Concept', 'BEGIN;\nUPDATE account SET balance = balance - 100 WHERE id = 1;\nUPDATE account SET balance = balance + 100 WHERE id = 2;\nCOMMIT;', 'Explain Consistency in ACID.'), ('What does Consistency mean in ACID?', 'A transaction must transition the database from one valid state to another valid state, preserving all constraints, foreign keys, triggers, and rules.', 'Easy', 'Concept', '', 'Explain Isolation in ACID.'), ('What does Isolation mean in ACID?', 'Concurrent transactions execute independently without interfering with each other; intermediate uncommitted states of one transaction are hidden from other transactions.', 'Easy', 'Concept', '', 'Explain Durability in ACID.'), ('What does Durability mean in ACID?', 'Once a transaction is committed, its changes are permanently recorded in non-volatile storage (WAL / redo logs) and will survive server crashes or power failures.', 'Easy', 'Concept', '', 'What are the 4 standard Transaction Isolation Levels?'), ('What are the 4 ANSI SQL Transaction Isolation Levels from lowest to highest?', '1. Read Uncommitted. 2. Read Committed. 3. Repeatable Read. 4. Serializable.', 'Intermediate', 'Concept', 'SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;', 'What is a Dirty Read?'), ('What is a Dirty Read in database transactions?', 'Transaction A reads data modified by Transaction B that has NOT yet been committed. If B rolls back, A read data that never truly existed.', 'Intermediate', 'Concept', '', 'What is a Non-Repeatable Read?'), ('What is a Non-Repeatable Read?', 'Transaction A reads a row, Transaction B updates or deletes that row and commits, and Transaction A re-reads the row obtaining different data.', 'Intermediate', 'Concept', '', 'What is a Phantom Read?'), ('What is a Phantom Read in database transactions?', "Transaction A runs a query with a range condition (e.g. salary > 50000), Transaction B inserts a new row matching that range and commits, and Transaction A re-runs the query seeing a new 'phantom' row.", 'Intermediate', 'Concept', '', 'Which isolation level prevents Dirty Reads?'), ('Which isolation level prevents Dirty Reads?', 'Read Committed (and higher). It ensures a query only reads data that has already been committed.', 'Easy', 'Concept', '', 'What is the default isolation level in PostgreSQL and MySQL?'), ('What is the default isolation level in MySQL vs PostgreSQL?', 'MySQL InnoDB defaults to REPEATABLE READ. PostgreSQL defaults to READ COMMITTED.', 'Intermediate', 'Comparison', '', 'What is a Deadlock in SQL and how does the engine resolve it?'), ('What is a Deadlock in relational databases?', 'A circular dependency where Transaction 1 holds a lock on resource A and waits for B, while Transaction 2 holds a lock on resource B and waits for A. Neither can proceed.', 'Intermediate', 'Concept', '', 'How does the database resolve a Deadlock?'), ('How does an RDBMS resolve deadlocks?', "The engine's deadlock detection algorithm detects the circular wait, chooses one transaction as the 'victim', forcefully aborts/rolls it back with a deadlock error, allowing the other to finish.", 'Intermediate', 'Concept', '', 'How can developers prevent deadlocks in application code?'), ('What is the best way to prevent deadlocks in multi-statement transactions?', 'Always access and lock tables/rows in the EXACT SAME consistent order across all application transactions.', 'Intermediate', 'Best Practice', '-- Both transactions update user 1 before user 2, never in opposite order', 'What is Pessimistic vs Optimistic Locking?'), ('What is the difference between Pessimistic and Optimistic Locking?', "Pessimistic Locking: Acquires locks upfront (SELECT ... FOR UPDATE) assuming conflicts will happen, blocking other readers/writers. Optimistic Locking: Assumes no conflicts, checks a 'version' column at commit time (WHERE id = 1 AND version = 5), failing if version changed.", 'Intermediate', 'Comparison', "SELECT * FROM tickets WHERE id = 10 FOR UPDATE; -- Pessimistic\nUPDATE tickets SET seat = '1A', version = version + 1 WHERE id = 10 AND version = 2; -- Optimistic", 'When should you use Optimistic Locking?'), ('When should Optimistic Locking be used over Pessimistic Locking?', 'In web applications with high concurrency and low contention (e.g. e-commerce checkouts) where long-lived database locks would destroy server throughput.', 'Intermediate', 'Scenario', '', "What does 'SELECT ... FOR UPDATE' do in SQL?"), ("What does 'SELECT ... FOR UPDATE' do?", 'It locks the selected rows with an exclusive write lock until the transaction commits or rolls back, preventing other transactions from updating, locking, or deleting those rows.', 'Intermediate', 'Practical', 'BEGIN;\nSELECT balance FROM accounts WHERE id = 1 FOR UPDATE;\n-- Now safe to compute and update balance\nUPDATE accounts SET balance = balance - 50 WHERE id = 1;\nCOMMIT;', 'What does SKIP LOCKED do?'), ("What does 'SELECT ... FOR UPDATE SKIP LOCKED' do in job queues?", 'It locks available rows and skips any rows currently locked by other concurrent worker transactions, enabling lock-free high-throughput background job processing.', 'Advanced', 'Practical', "SELECT * FROM jobs WHERE status = 'pending' LIMIT 1 FOR UPDATE SKIP LOCKED;", 'Why is SKIP LOCKED ideal for queue systems?'), ("Performance MCQ: What command displays the query optimizer's execution plan?", 'Option B is correct. EXPLAIN shows the execution plan.', 'Easy', 'MCQ', '', {'A': 'SHOW QUERY', 'B': 'EXPLAIN', 'C': 'ANALYZE QUERY', 'D': 'DESCRIBE PLAN'}, 'B', 'What does EXPLAIN ANALYZE do?'), ('ACID MCQ: Which property guarantees that once a transaction commits, its data survives server crashes?', 'Option D is correct. Durability guarantees persistence.', 'Easy', 'MCQ', '', {'A': 'Atomicity', 'B': 'Consistency', 'C': 'Isolation', 'D': 'Durability'}, 'D', 'What does Atomicity guarantee?'), ('Isolation MCQ: What phenomenon occurs when Transaction A reads uncommitted data from Transaction B?', 'Option A is correct. Dirty Read occurs on uncommitted data.', 'Easy', 'MCQ', '', {'A': 'Dirty Read', 'B': 'Non-Repeatable Read', 'C': 'Phantom Read', 'D': 'Lost Update'}, 'A', 'Which isolation level prevents it?'), ('Indexing MCQ: Which column is best suited for an index based on high selectivity?', 'Option C is correct. Email address has high uniqueness and selectivity.', 'Easy', 'MCQ', '', {'A': 'Gender (M/F)', 'B': 'Active status (true/false)', 'C': 'Email address', 'D': 'Country'}, 'C', 'Why is gender poor for indexing?'), ("Performance Debugging: A query 'SELECT * FROM users WHERE email LIKE %gmail.com' is extremely slow despite an index on email. Why?", "The leading wildcard '%' prevents the B-tree index from seeking from the root node, forcing a full table scan. B-trees only support prefix searches ('john%').", 'Intermediate', 'Debugging', "-- Full table scan:\nWHERE email LIKE '%gmail.com'\n-- Index seek supported:\nWHERE email LIKE 'john%'", 'How do you do fast suffix search?'), ('What is Database Sharding in horizontal scaling?', 'Partitioning a large database horizontally across multiple physical server nodes, where each shard holds a subset of rows based on a shard key.', 'Intermediate', 'Architecture', '', 'What is Database Replication (Primary-Replica)?'), ('What is Primary-Replica (Master-Slave) database replication?', 'The Primary node handles all write operations (INSERT, UPDATE, DELETE) and streams changes to read-only Replica nodes that serve read traffic.', 'Easy', 'Architecture', '', 'What is Replication Lag in read replicas?'), ('What is Replication Lag and what user problem can it cause?', "The delay between a write committing on the Primary and appearing on the Replica. If a user posts a comment and immediately refreshes, reading from a lagging replica might show the comment missing ('read-your-own-writes' issue).", 'Intermediate', 'Scenario', '', 'What is connection pooling in database clients?'), ('What is Connection Pooling and why is it essential in Node.js applications?', 'Opening a new TCP/database connection per HTTP request is slow and exhausts database connections. A connection pool keeps a pool of reusable open connections ready for queries.', 'Easy', 'Performance', 'const pool = new Pool({ max: 20 });\nconst client = await pool.connect();', 'What happens if all pool connections are in use?')]

MONGO_ITEMS = [('What is MongoDB and what category of databases does it belong to?', 'MongoDB is a source-available, cross-platform document-oriented NoSQL database that stores data in flexible, JSON-like BSON documents.', 'Easy', 'Concept', '', 'What does NoSQL mean?'), ('What does NoSQL stand for and how does it differ from SQL databases?', "NoSQL stands for 'Not Only SQL'. Unlike tabular relational databases with fixed schemas, NoSQL provides flexible schemas, horizontal scaling, and high-performance read/write operations.", 'Easy', 'Comparison', '', 'What is a Document in MongoDB?'), ('What is a Document in MongoDB?', 'A document is a basic unit of data in MongoDB, composed of field-and-value pairs structured similarly to JSON objects.', 'Easy', 'Concept', '{ "name": "Alice", "age": 25, "skills": ["React", "Node"] }', 'What is a Collection in MongoDB?'), ('What is a Collection in MongoDB?', 'A collection is a grouping of MongoDB documents, analogous to a table in a relational database. Collections do not enforce a rigid schema by default.', 'Easy', 'Concept', "db.createCollection('users');", 'How do MongoDB terms map to SQL terms?'), ('How do RDBMS terms map to MongoDB concepts?', 'Database -> Database. Table -> Collection. Row -> Document. Column -> Field. Primary Key -> _id (ObjectId). Join -> $lookup / embedding.', 'Easy', 'Comparison', '', 'What is BSON and how does it differ from JSON?'), ('What is BSON and why does MongoDB use BSON instead of plain JSON?', 'BSON stands for Binary JSON. It is a binary-encoded serialization of JSON documents that supports additional data types (Date, ObjectId, Binary, Int32/64) and enables fast traversal.', 'Easy', 'Concept', '', 'What extra data types does BSON support that standard JSON lacks?'), ('What data types are supported in BSON that standard JSON does NOT support?', 'Date, ObjectId, Binary data, Decimal128 (high-precision numbers), 32-bit and 64-bit integers, Regular Expression, and Timestamp.', 'Intermediate', 'Comparison', '', 'What is the maximum document size limit in MongoDB?'), ('What is the maximum allowed BSON document size in MongoDB and why does this limit exist?', 'The maximum document size is 16 Megabytes (16MB). This limit prevents runaway memory usage and ensures high network streaming and query performance.', 'Easy', 'Concept', '', 'How do you store files or datasets larger than 16MB in MongoDB?'), ('How does MongoDB store files larger than the 16MB document limit?', 'Using GridFS. GridFS automatically splits large files (videos, PDFs, images) into smaller 255KB chunks stored across two collections: fs.files and fs.chunks.', 'Intermediate', 'Concept', '', 'What is the _id field in MongoDB documents?'), ("What is the purpose of the '_id' field in every MongoDB document?", "The '_id' field is the mandatory primary key for every document in a collection. It is automatically indexed with a unique index and cannot be modified once set.", 'Easy', 'Concept', '_id: ObjectId("6501f2a4b3d8e9f1a2b3c4d5")', 'Can you provide a custom _id instead of an ObjectId?'), ("Can you assign a custom value to '_id' instead of using an ObjectId?", "Yes! You can set '_id' to any unique BSON data type (string, integer, UUID) during document insertion (e.g. { _id: 'user_101', name: 'Bob' }).", 'Easy', 'Concept', "db.users.insertOne({ _id: 'EMP100', name: 'Alice' });", 'What is an ObjectId in MongoDB and what are its components?'), ('What is an ObjectId and what is its 12-byte internal structure?', 'An ObjectId is a 12-byte (24-character hexadecimal) unique identifier composed of: 1. 4-byte timestamp (seconds since Unix epoch). 2. 5-byte random value (machine/process unique). 3. 3-byte incrementing counter.', 'Intermediate', 'Concept', '', 'Can you extract the creation timestamp directly from an ObjectId?'), ('How do you extract the creation date and time from an ObjectId in MongoDB?', "Use the getTimestamp() method: ObjectId('...').getTimestamp(). It extracts the first 4 bytes of the ID.", 'Easy', 'Practical', 'const id = new ObjectId();\nconsole.log(id.getTimestamp()); // Returns Date object', 'Are documents with ObjectIds naturally sorted by creation time?'), ('Are MongoDB documents roughly sorted by creation time if sorted by _id?', 'Yes! Because the first 4 bytes of an ObjectId represent the Unix epoch timestamp, sorting by _id (sort({ _id: 1 })) sorts documents chronologically.', 'Easy', 'Concept', 'db.logs.find().sort({ _id: -1 }).limit(10); // 10 newest logs', 'What is dynamic schema (schema-less) in MongoDB?'), ("What does 'schema-less' or dynamic schema mean in MongoDB?", 'Documents within the same collection do not need to have the same fields or data types; fields can vary from document to document dynamically.', 'Easy', 'Concept', "{ name: 'Alice' }\n{ name: 'Bob', age: 30, address: { city: 'NY' } }", 'What is Schema Validation in MongoDB?'), ('Does MongoDB support schema validation rules?', 'Yes! MongoDB supports JSON Schema validation ($jsonSchema) configured on collections to enforce required fields, types, and value constraints at the database level.', 'Intermediate', 'Concept', "db.createCollection('students', {\n  validator: { $jsonSchema: { required: ['name', 'email'] } }\n});", 'What is Mongoose in Node.js development?'), ('What is Mongoose and what role does it play in the MERN stack?', 'Mongoose is an Object Data Modeling (ODM) library for Node.js and MongoDB. It provides schema validation, type casting, middleware (hooks), and model query helpers.', 'Easy', 'Concept', "const mongoose = require('mongoose');\nconst userSchema = new mongoose.Schema({ name: String });", 'What is the difference between mongod and mongos?'), ("What is the difference between 'mongod' and 'mongos' processes?", "'mongod' is the core database daemon process that handles data storage, queries, and background jobs. 'mongos' is the routing service used in sharded clusters.", 'Intermediate', 'Concept', '', 'What is mongosh in modern MongoDB?'), ("What is 'mongosh'?", 'mongosh (MongoDB Shell) is the modern interactive JavaScript command-line environment for querying and administering MongoDB databases.', 'Easy', 'Concept', '$ mongosh\ntest> show dbs', 'How do you switch databases in mongosh?'), ('How do you switch or create a database in MongoDB shell?', "Use: 'use database_name'. MongoDB creates the database lazily when the first document is inserted.", 'Easy', 'Practical', 'use store_db;', 'How do you view all collections in the current database?'), ('What command lists all collections in the current database?', "Run 'show collections' or 'db.getCollectionNames()'.", 'Easy', 'Practical', 'show collections;', 'What command deletes the current database?'), ('How do you drop the current database in MongoDB?', "Run 'db.dropDatabase()'.", 'Easy', 'Practical', 'db.dropDatabase();', 'What command deletes a collection?'), ('How do you delete a collection and all its indexes in MongoDB?', "Run 'db.collection_name.drop()'.", 'Easy', 'Practical', 'db.temp_users.drop();', 'What are capped collections in MongoDB?'), ('What is a Capped Collection in MongoDB?', 'A fixed-size circular collection that automatically overwrites its oldest documents once it reaches its allocated maximum byte size or document count (ideal for logs/caches).', 'Intermediate', 'Concept', "db.createCollection('app_logs', { capped: true, size: 5242880, max: 5000 });", 'Can you delete documents from a capped collection?'), ('Can you manually delete individual documents from a capped collection in MongoDB?', 'No! In capped collections, documents cannot be explicitly deleted (db.collection.deleteOne() throws an error). They are aged out automatically FIFO.', 'Intermediate', 'Concept', '', 'What is WiredTiger in MongoDB?'), ('What is WiredTiger?', 'WiredTiger is the default, high-performance pluggable storage engine in MongoDB, providing document-level concurrency control, checkpointing, and Snappy compression.', 'Intermediate', 'Concept', '', 'What level of locking does WiredTiger provide in MongoDB?'), ('What locking granularity does the WiredTiger storage engine use?', 'Document-level locking. Multiple concurrent write operations can modify different documents within the same collection simultaneously.', 'Intermediate', 'Concept', '', 'What is the CAP Theorem and where does MongoDB sit?'), ('Where does MongoDB fit in the CAP Theorem?', 'MongoDB is fundamentally a CP (Consistency and Partition Tolerance) system by default. In network partitions, it prioritizes strong data consistency over availability.', 'Advanced', 'Architecture', '', 'What is a Replica Set in MongoDB?'), ('What is a MongoDB Replica Set?', 'A group of mongod processes maintaining the exact same data set, consisting of one Primary node (accepts writes) and multiple Secondary nodes (replicate data for high availability and failover).', 'Easy', 'Architecture', '', 'What happens if the Primary node in a replica set crashes?'), ('How does automated failover work in a MongoDB Replica Set?', 'The remaining secondary nodes hold an election. The node with the most up-to-date oplog is automatically elected as the new Primary within seconds.', 'Intermediate', 'Architecture', '', 'What is the Oplog (Operations Log) in MongoDB?'), ('What is the Oplog (local.oplog.rs) in MongoDB?', 'A capped collection on replica set nodes that records a rolling log of all data-modifying write operations, used by secondary nodes to sync state asynchronously.', 'Advanced', 'Concept', '', 'What is Read Preference in MongoDB replica sets?'), ('What is Read Preference in MongoDB and what are the options?', 'It determines which replica set nodes queries are routed to: primary (default), primaryPreferred, secondary (routes to read-only replicas), secondaryPreferred, nearest.', 'Intermediate', 'Concept', "db.collection.find().readPref('secondary')", 'What is Write Concern in MongoDB?'), ('What is Write Concern (w) in MongoDB?', "It specifies the level of acknowledgment requested from MongoDB for write operations (e.g. w: 1 acknowledges primary only; w: 'majority' acknowledges a majority of replica nodes).", 'Intermediate', 'Concept', "db.orders.insertOne(doc, { writeConcern: { w: 'majority', wtimeout: 5000 } });", 'What is j (journal) in write concern?'), ("What does 'j: true' in Write Concern specify?", 'It requests acknowledgment that the write operation has been written to the on-disk journal file, ensuring durability against server power loss.', 'Intermediate', 'Concept', "{ writeConcern: { w: 'majority', j: true } }", 'What is Sharding in MongoDB?'), ('What is Sharding in MongoDB?', 'Horizontal scaling architecture that distributes large datasets and high query loads across multiple independent servers (shards) using a shard key.', 'Intermediate', 'Architecture', '', 'What are the components of a MongoDB Sharded Cluster?'), ('What are the 3 core components of a MongoDB Sharded Cluster?', '1. Shards (replica sets holding data partitions). 2. Mongos (query routers). 3. Config Servers (store cluster metadata and routing table).', 'Intermediate', 'Architecture', '', 'What is a Shard Key?'), ('What is a Shard Key in MongoDB?', 'A field (or fields) present in every document of a collection that MongoDB uses to determine which shard should store each document.', 'Intermediate', 'Concept', "sh.shardCollection('store.orders', { customer_id: 'hashed' });", 'What is the difference between Ranged Sharding and Hashed Sharding?'), ('What is the difference between Ranged Sharding and Hashed Sharding?', 'Ranged Sharding partitions data into ranges based on shard key values (good for range queries, but can cause write hotspots). Hashed Sharding computes an MD5 hash of the key to evenly scatter writes across all shards.', 'Advanced', 'Comparison', '', 'Mongo Basics MCQ: What is the maximum document size in MongoDB?'), ('Mongo Basics MCQ: What is the maximum size of a single BSON document in MongoDB?', 'Option C is correct. 16 Megabytes is the hard limit.', 'Easy', 'MCQ', '', {'A': '4MB', 'B': '8MB', 'C': '16MB', 'D': '32MB'}, 'C', 'How do you store files larger than 16MB?'), ('Mongo Basics MCQ: How many bytes long is a MongoDB ObjectId?', 'Option B is correct. An ObjectId is exactly 12 bytes (24 hex characters).', 'Easy', 'MCQ', '', {'A': '8 bytes', 'B': '12 bytes', 'C': '16 bytes', 'D': '24 bytes'}, 'B', 'How many characters is its hex string?'), ('Mongo Basics MCQ: Which storage engine provides document-level locking in modern MongoDB?', 'Option B is correct. WiredTiger provides document-level locking.', 'Easy', 'MCQ', '', {'A': 'MMAPv1', 'B': 'WiredTiger', 'C': 'InnoDB', 'D': 'RocksDB'}, 'B', 'What engine did it replace?'), ('Mongo Basics MCQ: In a replica set, which node type handles write operations by default?', 'Option A is correct. Only the Primary node accepts write operations.', 'Easy', 'MCQ', '', {'A': 'Primary', 'B': 'Secondary', 'C': 'Arbiter', 'D': 'Hidden'}, 'A', 'Can secondary nodes accept writes?'), ('Mongo Basics Debugging: A user tries to insert a document of size 20MB directly into a collection and it fails. Why?', 'The document exceeds the 16MB BSON document size limit. Solution: split the data across multiple documents or use GridFS for large binaries.', 'Easy', 'Debugging', '-- Error: Document exceeds maximum allowed BSON size (16777216 bytes)', 'What tool handles files > 16MB?'), ('What method inserts a single document into a MongoDB collection?', 'Use db.collection.insertOne(document). It returns an object with acknowledged: true and insertedId.', 'Easy', 'Practical', "db.users.insertOne({ name: 'Charlie', email: 'charlie@test.com' });", 'What method inserts multiple documents?'), ('How do you insert multiple documents in a single operation in MongoDB?', 'Use db.collection.insertMany([doc1, doc2, ...]).', 'Easy', 'Practical', "db.products.insertMany([\n  { item: 'pen', price: 1.5 },\n  { item: 'notebook', price: 3.0 }\n]);", 'What does ordered: false do in insertMany?'), ('What is the difference between ordered and unordered bulk inserts in insertMany?', 'ordered: true (default) stops immediately on the first error. ordered: false continues inserting remaining valid documents even if one fails.', 'Intermediate', 'Concept', 'db.users.insertMany(docs, { ordered: false });', 'What does db.collection.find() return?'), ('What does db.collection.find(query, projection) return in MongoDB?', 'It returns a Cursor pointing to the matching documents (it does not load all documents into memory at once).', 'Easy', 'Concept', "const cursor = db.users.find({ status: 'active' });", 'What does findOne() return?'), ('What is the difference between find() and findOne()?', 'find() returns a cursor to multiple documents. findOne() returns the single first matching document directly as an object (or null if not found).', 'Easy', 'Comparison', "const user = db.users.findOne({ _id: ObjectId('...') });", 'How do you format output in mongosh?'), ('What does .pretty() do in MongoDB cursor output?', 'It formats the printed BSON documents with indentation and line breaks for readability (default behavior in modern mongosh).', 'Easy', 'Practical', 'db.users.find().pretty();', 'How do you project (include/exclude) specific fields in find()?'), ('How does Field Projection work in MongoDB find queries?', 'Pass a projection object as the second argument: { name: 1, email: 1, _id: 0 } (1 to include, 0 to exclude).', 'Easy', 'Practical', 'db.users.find({}, { name: 1, email: 1, _id: 0 });', 'Can you mix 1 and 0 in projection?'), ('Can you mix 1 (inclusion) and 0 (exclusion) in a single projection object?', "No! You cannot mix inclusion and exclusion in the same projection, EXCEPT for the '_id' field (which is included by default and must be explicitly suppressed with _id: 0).", 'Easy', 'Concept', '// VALID:\n{ name: 1, email: 1, _id: 0 }\n// INVALID:\n{ name: 1, password: 0 }', 'What does updateOne() do?'), ('What does db.collection.updateOne(filter, update, options) do?', 'It updates the first document that matches the filter criteria.', 'Easy', 'Practical', "db.users.updateOne({ email: 'john@test.com' }, { $set: { isVerified: true } });", 'What does updateMany() do?'), ('What does db.collection.updateMany(filter, update, options) do?', 'It updates ALL documents that match the filter criteria.', 'Easy', 'Practical', "db.products.updateMany({ category: 'books' }, { $inc: { price: 2 } });", 'What happens if you update without an update operator like $set?'), ('Why is using update operators ($set) mandatory in updateOne / updateMany?', 'Without update operators like $set, MongoDB replaces the entire document structure with the provided object, wiping out all unspecified fields!', 'Easy', 'Scenario', '-- WRONG (replaces entire doc):\ndb.users.updateOne({ _id: 1 }, { age: 30 });\n-- CORRECT:\ndb.users.updateOne({ _id: 1 }, { $set: { age: 30 } });', 'What does the $set operator do?'), ('What does the $set operator do in MongoDB updates?', 'It sets or replaces the value of specified fields in a document. If the field does not exist, $set creates it.', 'Easy', 'Practical', "db.users.updateOne({ _id: 1 }, { $set: { status: 'active', updatedAt: new Date() } });", 'What does $unset operator do?'), ('What does the $unset operator do in MongoDB?', 'It deletes (removes) a specified field completely from a document.', 'Easy', 'Practical', "db.users.updateOne({ _id: 1 }, { $unset: { tempToken: '' } });", 'What does $inc operator do?'), ('What does the $inc operator do in MongoDB updates?', 'It increments (or decrements with negative numbers) the value of a numeric field by a specified amount atomically.', 'Easy', 'Practical', 'db.posts.updateOne({ _id: 10 }, { $inc: { viewCount: 1, likes: -1 } });', 'Why is $inc better than read-modify-save for counters?'), ('Why is $inc superior to fetching, modifying in Node.js, and saving back?', '$inc is executed atomically inside the database engine, avoiding race conditions when multiple concurrent requests update the counter simultaneously.', 'Easy', 'Best Practice', '', 'What does the $mul operator do?'), ('What does the $mul operator do in MongoDB?', 'It multiplies the numeric value of a field by the specified multiplier.', 'Easy', 'Practical', 'db.products.updateOne({ _id: 5 }, { $mul: { price: 1.10 } }); // 10% increase', 'What does the $min and $max update operators do?'), ('What do $min and $max update operators do?', '$min updates the field only if the specified value is LESS than the current value. $max updates only if the value is GREATER than current value.', 'Intermediate', 'Concept', 'db.scores.updateOne({ _id: 1 }, { $max: { highScore: 950 } });', 'What is an upsert in MongoDB?'), ("What does the 'upsert: true' option do in update operations?", 'If matching documents are found, it updates them. If NO matching document is found, it inserts a new document combining the filter and update fields.', 'Easy', 'Practical', "db.views.updateOne(\n  { page: '/home' },\n  { $inc: { count: 1 } },\n  { upsert: true }\n);", 'What is replaceOne()?'), ('What does db.collection.replaceOne(filter, replacement, options) do?', 'It completely replaces the entire document matching the filter (except for the immutable _id field) with the new document.', 'Easy', 'Concept', "db.users.replaceOne({ _id: 1 }, { name: 'Dan', role: 'guest' });", 'What does deleteOne() do?'), ('What does db.collection.deleteOne(filter) do in MongoDB?', 'It deletes the first document that matches the filter criteria.', 'Easy', 'Practical', "db.users.deleteOne({ _id: ObjectId('...') });", 'What does deleteMany() do?'), ('What does db.collection.deleteMany(filter) do?', "It deletes all documents matching the filter criteria. Passing '{}' deletes all documents in the collection.", 'Easy', 'Practical', "db.logs.deleteMany({ status: 'archived' });", 'What does findOneAndUpdate() return?'), ('What is the difference between updateOne() and findOneAndUpdate()?', 'updateOne returns a write result status ({ matchedCount, modifiedCount }). findOneAndUpdate atomically modifies and returns the document itself.', 'Intermediate', 'Comparison', "const updatedDoc = await db.users.findOneAndUpdate(\n  { _id: 1 },\n  { $inc: { balance: -10 } },\n  { returnDocument: 'after' }\n);", "What does returnDocument: 'after' / new: true do?"), ('How do you make findOneAndUpdate return the modified document instead of original?', "In native driver / mongosh, pass { returnDocument: 'after' }. In Mongoose, pass { new: true }.", 'Easy', 'Practical', 'User.findOneAndUpdate({ _id }, { $set }, { new: true });', 'What does findOneAndDelete() do?'), ('What does findOneAndDelete(filter) do in MongoDB?', 'It atomically deletes the first matching document and returns the deleted document data to the client.', 'Easy', 'Practical', "const job = await db.jobs.findOneAndDelete({ status: 'queued' });", 'How do you append an item to an array field in MongoDB?'), ('What does the $push operator do in MongoDB updates?', "It appends a specified value to an array field. If the array field doesn't exist, it creates the array.", 'Easy', 'Practical', "db.users.updateOne({ _id: 1 }, { $push: { hobbies: 'chess' } });", 'How do you push multiple items at once to an array?'), ('How do you append multiple values to an array with $push?', "Use the $each modifier: { $push: { tags: { $each: ['web', 'database', 'backend'] } } }.", 'Intermediate', 'Practical', "db.articles.updateOne({ _id: 1 }, { $push: { tags: { $each: ['node', 'mongo'] } } });", 'How do you keep only the last N items in an array during $push?'), ('How do you maintain a fixed-length array (e.g. last 5 notifications) during $push?', 'Combine $push with $each, $sort, and $slice modifiers: { $push: { logs: { $each: [newLog], $slice: -5 } } }.', 'Advanced', 'Practical', 'db.users.updateOne({ _id: 1 }, {\n  $push: { recentLogins: { $each: [new Date()], $slice: -5 } }\n});', 'What does $addToSet operator do?'), ('What does the $addToSet operator do and how does it differ from $push?', '$addToSet adds an element to an array only if the element does NOT already exist in the array (prevents duplicate array items). $push adds regardless of duplicates.', 'Easy', 'Comparison', "db.users.updateOne({ _id: 1 }, { $addToSet: { roles: 'admin' } });", 'What does $pop operator do?'), ('What does the $pop operator do in MongoDB array updates?', 'It removes either the first element ({ $pop: { array: -1 } }) or the last element ({ $pop: { array: 1 } }) from an array.', 'Easy', 'Practical', 'db.queue.updateOne({ _id: 1 }, { $pop: { items: -1 } }); // Removes first item', 'What does $pull operator do?'), ('What does the $pull operator do in MongoDB array updates?', 'It removes all instances of a value or all items matching a condition from an array.', 'Easy', 'Practical', "db.users.updateOne({ _id: 1 }, { $pull: { hobbies: 'tennis' } });", 'What does $pullAll do?'), ('What is the difference between $pull and $pullAll?', "$pull removes items matching a value or condition. $pullAll removes a list of exact matching values: { $pullAll: { tags: ['old', 'deprecated'] } }.", 'Intermediate', 'Comparison', '', 'What is the positional operator ($) in array updates?'), ("What does the positional operator '$' do in MongoDB array updates?", 'It acts as a placeholder for the FIRST array element that matched the query filter, updating that specific element.', 'Intermediate', 'Practical', "db.grades.updateOne(\n  { _id: 1, 'scores.type': 'quiz' },\n  { $set: { 'scores.$.score': 100 } }\n);", 'What does the all positional operator ($[]) do?'), ("What does the all positional operator '$[]' do in MongoDB updates?", "It updates ALL elements in an array: { $set: { 'grades.$[].score': 0 } }.", 'Intermediate', 'Practical', "db.students.updateOne({ _id: 1 }, { $inc: { 'scores.$[]': 5 } }); // +5 to all scores", 'What are filtered positional array filters ($[identifier])?'), ('What are arrayFilters in MongoDB updates?', 'arrayFilters allow updating only array elements that satisfy specific conditions within arrayFilter definitions: $[elem].', 'Advanced', 'Practical', "db.students.updateOne(\n  { _id: 1 },\n  { $set: { 'scores.$[elem].grade': 'A' } },\n  { arrayFilters: [{ 'elem.score': { $gte: 90 } }] }\n);", 'CRUD MCQ: Which update operator increments a numeric field atomically in MongoDB?'), ('CRUD MCQ: Which operator increments a number field atomically without race conditions?', 'Option B is correct. $inc updates numbers atomically.', 'Easy', 'MCQ', '', {'A': '$add', 'B': '$inc', 'C': '$plus', 'D': '$append'}, 'B', 'Can $inc decrement?'), ('CRUD MCQ: Which operator adds an item to an array only if the item does not already exist?', 'Option C is correct. $addToSet avoids duplicates.', 'Easy', 'MCQ', '', {'A': '$push', 'B': '$append', 'C': '$addToSet', 'D': '$insert'}, 'C', 'What does $push do instead?'), ('CRUD MCQ: What projection syntax suppresses the default _id field?', 'Option B is correct. {_id: 0} suppresses _id.', 'Easy', 'MCQ', '', {'A': '{_id: false}', 'B': '{_id: 0}', 'C': '{_id: null}', 'D': "{hide: '_id'}"}, 'B', 'Is _id included by default?'), ('CRUD Coding: Write a query to find all users with age >= 21 and return only their name and email without _id.', 'db.users.find({ age: { $gte: 21 } }, { name: 1, email: 1, _id: 0 });', 'Easy', 'Coding', 'db.users.find(\n  { age: { $gte: 21 } },\n  { name: 1, email: 1, _id: 0 }\n);', 'What does $gte stand for?'), ("CRUD Coding: Write an update query to add a tag 'mern' to the tags array of an article if not already present.", "db.articles.updateOne({ _id: 1 }, { $addToSet: { tags: 'mern' } });", 'Easy', 'Coding', "db.articles.updateOne(\n  { _id: articleId },\n  { $addToSet: { tags: 'mern' } }\n);", "What happens if 'mern' already exists?"), ("CRUD Debugging: A developer wrote db.users.updateOne({ _id: 1 }, { name: 'Bob' }); Why did all other fields vanish?", "They omitted the $set operator. Passing a raw object replaces the entire document. Use { $set: { name: 'Bob' } } instead.", 'Easy', 'Debugging', "-- FIX:\ndb.users.updateOne({ _id: 1 }, { $set: { name: 'Bob' } });", 'How do you prevent this mistake?'), ('What does cursor.limit(n) do in MongoDB?', 'It constrains the maximum number of documents returned by the cursor to n.', 'Easy', 'Practical', 'db.products.find().limit(10);', 'What does cursor.skip(n) do?'), ('What does cursor.skip(n) do in MongoDB?', 'It skips the first n documents before beginning to return results from the cursor (used for pagination).', 'Easy', 'Practical', 'db.products.find().skip(20).limit(10); // Page 3', 'Why is skip() slow for deep pagination (e.g. skip(100000))?'), ('Why is cursor.skip(100000) slow for deep pagination?', 'MongoDB must scan and discard 100,000 documents from disk in memory. Use range-based pagination (find({ _id: { $gt: lastId } })) instead.', 'Intermediate', 'Performance', '', 'How does cursor.sort() work in MongoDB?'), ('How do you sort documents in MongoDB queries?', 'Use cursor.sort({ field: 1 }) for ascending, or -1 for descending.', 'Easy', 'Practical', 'db.users.find().sort({ createdAt: -1 });', 'What is the execution order between sort(), skip(), and limit() on a cursor?'), ('Regardless of method call order in code, what order does MongoDB execute sort, skip, and limit?', 'MongoDB always executes: 1. sort() first, then 2. skip(), then 3. limit().', 'Intermediate', 'Concept', 'db.users.find().limit(5).skip(10).sort({ age: 1 }); // Sorted first!', 'What does cursor.countDocuments() do?'), ('What is the difference between estimatedDocumentCount() and countDocuments()?', 'estimatedDocumentCount() reads collection metadata instantly (fast, O(1), no filter). countDocuments(filter) scans documents/indexes to return an exact count.', 'Intermediate', 'Comparison', 'db.users.estimatedDocumentCount(); // Fast\ndb.users.countDocuments({ active: true }); // Filtered', 'What does cursor.toArray() do in Node.js driver?'), ('What does cursor.toArray() do in the MongoDB Node.js driver?', 'It iterates the cursor completely and returns a Promise that resolves with an array of all fetched documents in memory.', 'Easy', 'Practical', "const users = await db.collection('users').find().toArray();", 'Why should toArray() be avoided on 1 million documents?'), ('Why should cursor.toArray() be avoided on huge collections?', 'Loading 1 million documents into memory at once exhausts Node.js V8 heap memory (~1.4GB) and crashes the server. Stream with cursor.forEach() or async iterator.', 'Intermediate', 'Scenario', '', 'What is bulkWrite() in MongoDB?'), ('What is db.collection.bulkWrite() in MongoDB?', 'It executes a batch of heterogeneous write operations (insertOne, updateOne, updateMany, deleteOne, replaceOne) in a single database round-trip.', 'Intermediate', 'Practical', "db.users.bulkWrite([\n  { insertOne: { document: { name: 'A' } } },\n  { updateOne: { filter: { name: 'B' }, update: { $set: { x: 1 } } } }\n]);", 'Why is bulkWrite beneficial?'), ('What are comparison query operators in MongoDB?', '$eq (equal), $ne (not equal), $gt (greater than), $gte (greater than or equal), $lt (less than), $lte (less than or equal), $in (in array), $nin (not in array).', 'Easy', 'Concept', 'db.items.find({ price: { $gte: 20, $lte: 50 } });', 'What is the difference between $in and $nin?'), ('What does the $in operator do in MongoDB queries?', "Matches documents where a field's value equals ANY value in the specified array: { status: { $in: ['active', 'pending'] } }.", 'Easy', 'Concept', "db.orders.find({ status: { $in: ['paid', 'shipped'] } });", 'What does the $nin operator do?'), ('What does the $nin operator do?', "Matches documents where the field's value does NOT equal any value in the array, OR where the field does not exist.", 'Easy', 'Concept', "db.users.find({ role: { $nin: ['admin', 'moderator'] } });", 'What are the logical query operators in MongoDB?'), ('What are the 4 logical query operators in MongoDB?', '$and (all conditions true), $or (at least one condition true), $not (negates condition), $nor (none of the conditions true).', 'Easy', 'Concept', 'db.inventory.find({ $or: [{ qty: { $lt: 20 } }, { price: 10 }] });', 'When is an explicit $and operator required in MongoDB?'), ('When must you use an explicit $and operator instead of implicit comma conditions?', 'When specifying multiple expressions on the same field or operator (e.g. { $and: [{ price: { $ne: 10 } }, { price: { $exists: true } }] }).', 'Intermediate', 'Concept', '', 'What does the $not operator do?'), ('What does the $not operator do in MongoDB queries?', 'It inverts the effect of a query operator, matching documents where the expression is false or the field does not exist.', 'Intermediate', 'Concept', 'db.inventory.find({ price: { $not: { $gt: 50 } } });', 'What does the $nor operator do?'), ('What does the $nor operator do?', 'Matches documents that fail to match ALL clauses in the given array (neither condition A nor condition B is true).', 'Intermediate', 'Concept', "db.users.find({ $nor: [{ status: 'banned' }, { strikes: { $gt: 3 } }] });", 'What does the $exists operator do?'), ('What does the $exists operator do in MongoDB?', 'It matches documents that contain the specified field, regardless of whether the field value is null or truthy: { field: { $exists: true } }.', 'Easy', 'Concept', 'db.users.find({ phone: { $exists: true } });', 'What is the difference between { phone: null } and { phone: { $exists: false } }?'), ('What is the difference between querying { field: null } vs { field: { $exists: false } } in MongoDB?', '{ field: null } matches documents where the field explicitly has the value null AND documents where the field does not exist. { $exists: false } matches ONLY documents where the field is missing.', 'Intermediate', 'Comparison', '', 'What does the $type operator do?'), ('What does the $type operator do in MongoDB?', "It selects documents where the field's value matches a specified BSON data type (e.g. 'string', 'number', 'array', 'date', 'objectId').", 'Easy', 'Practical', "db.users.find({ age: { $type: 'int' } });", 'How do you perform regex searches in MongoDB?'), ('How do you perform a regular expression pattern search in MongoDB?', "Use the $regex operator (or JavaScript regex literals): db.users.find({ name: { $regex: '^A', $options: 'i' } });.", 'Easy', 'Practical', 'db.users.find({ email: /@gmail\\.com$/i });', 'Why are leading wildcard regex queries (/.*test/) slow in MongoDB?'), ("Why can't regular expressions with leading wildcards ({ name: /.*smith/i }) use standard indexes?", 'B-Tree indexes are sorted alphabetically from left to right; a leading wildcard prevents index tree seeking, forcing a collection scan.', 'Intermediate', 'Performance', '', 'What does the $expr operator do in MongoDB?'), ('What does the $expr operator do in MongoDB queries?', 'It allows using aggregation expressions and comparing fields from the SAME document within a regular find() query!', 'Intermediate', 'Concept', "db.monthlyBudget.find({ $expr: { $gt: ['$spent', '$budget'] } });", 'Give an example of comparing two fields in the same document.'), ('Query Coding: Find all products where quantity in stock is less than the reorderLevel field.', "db.products.find({ $expr: { $lt: ['$stock', '$reorderLevel'] } });", 'Easy', 'Coding', "db.products.find({\n  $expr: { $lt: ['$stock', '$reorderLevel'] }\n});", 'Can normal find without $expr compare two fields?'), ('Can a standard MongoDB query compare two document fields without $expr?', "No! Standard find({ fieldA: '$fieldB' }) treats '$fieldB' as a literal string value. $expr is required to interpret '$fieldB' as a field reference.", 'Intermediate', 'Concept', '', 'How do you query array fields for an exact element?'), ('How does querying a scalar value on an array field work in MongoDB?', "Querying { tags: 'red' } automatically searches the 'tags' array and matches if 'red' is ANY element in that array.", 'Easy', 'Concept', "db.products.find({ tags: 'electronics' });", 'What does the $all operator do?'), ('What does the $all operator do in MongoDB array queries?', 'It matches arrays that contain ALL the specified elements, regardless of order or extra elements.', 'Easy', 'Concept', "db.products.find({ tags: { $all: ['appliance', 'kitchen'] } });", 'What does the $size operator do?'), ('What does the $size operator do in array queries?', 'It matches documents where an array field contains exactly the specified number of elements: { comments: { $size: 3 } }.', 'Easy', 'Concept', 'db.articles.find({ tags: { $size: 2 } });', 'Can $size check for ranges (like size > 5)?'), ('Can $size be used for range queries (e.g. array length > 5)?', "No! $size only accepts an exact integer. For range comparisons, use $expr: { $expr: { $gt: [{ $size: '$tags' }, 5] } } or store an arrayLength counter.", 'Intermediate', 'Practical', "db.posts.find({ $expr: { $gt: [{ $size: '$comments' }, 5] } });", 'What does $elemMatch do in array queries?'), ('What is the $elemMatch operator in MongoDB and why is it essential for arrays of subdocuments?', '$elemMatch ensures that a SINGLE subdocument in an array satisfies ALL specified conditions (rather than condition A matching one element and condition B matching another).', 'Intermediate', 'Concept', "db.students.find({\n  grades: { $elemMatch: { subject: 'Math', score: { $gte: 90 } } }\n});", 'What happens without $elemMatch when querying arrays of subdocuments?'), ('Why does querying array of objects without $elemMatch yield false positives?', "Querying { 'grades.subject': 'Math', 'grades.score': 90 } matches if ONE element has subject 'Math' and a DIFFERENT element has score 90.", 'Intermediate', 'Scenario', '', 'How do you query nested fields in subdocuments?'), ('How do you query a nested field inside an embedded subdocument?', "Use dot notation wrapped in quotes: db.users.find({ 'address.city': 'New York' });.", 'Easy', 'Practical', "db.users.find({ 'profile.settings.notifications': true });", 'Why must dot notation fields be enclosed in quotes in JavaScript/MongoDB?'), ('Why must dot notation field paths be quoted in queries?', "Without quotes, JavaScript parses 'address.city' as an object property access on a variable named 'address', causing a ReferenceError.", 'Easy', 'Concept', '', 'What does the $slice projection operator do?'), ('What does the $slice operator do in find() projections?', 'It limits the number of array elements returned in the query response (e.g. return only the 3 most recent comments).', 'Easy', 'Practical', 'db.posts.find({ _id: 1 }, { comments: { $slice: -3 } }); // Last 3 comments', 'How does $slice support pagination for arrays?'), ('How do you paginate elements inside an array field using $slice?', 'Pass an array [skip, limit]: { comments: { $slice: [20, 10] } } (skips 20 comments and returns the next 10).', 'Intermediate', 'Practical', 'db.articles.find({ _id: 10 }, { comments: { $slice: [0, 5] } });', 'Query MCQ: Which operator matches documents where a field value equals ANY value in an array?'), ('Query MCQ: Which comparison operator tests if a field value matches any element in a list?', 'Option B is correct. $in checks membership.', 'Easy', 'MCQ', '', {'A': '$has', 'B': '$in', 'C': '$all', 'D': '$any'}, 'B', 'What does $all test?'), ('Query MCQ: Which operator ensures multiple conditions match the SAME array element?', 'Option C is correct. $elemMatch enforces single-element condition matching.', 'Easy', 'MCQ', '', {'A': '$all', 'B': '$in', 'C': '$elemMatch', 'D': '$slice'}, 'C', 'Why is it used on arrays of objects?'), ('Query MCQ: Which operator allows comparing two fields from the same document in find()?', 'Option D is correct. $expr enables aggregation expressions in queries.', 'Easy', 'MCQ', '', {'A': '$where', 'B': '$compare', 'C': '$same', 'D': '$expr'}, 'D', 'Can standard find compare fields?'), ("Query Coding: Find all users whose age is between 18 and 30 (inclusive) and who have 'developer' in their skills array.", "db.users.find({ age: { $gte: 18, $lte: 30 }, skills: 'developer' });", 'Easy', 'Coding', "db.users.find({\n  age: { $gte: 18, $lte: 30 },\n  skills: 'developer'\n});", 'Is $all needed for a single skill?'), ("Query Coding: Find all documents where the 'email' field exists and is not null.", 'db.users.find({ email: { $exists: true, $ne: null } });', 'Easy', 'Coding', 'db.users.find({\n  email: { $exists: true, $ne: null }\n});', 'Why is $ne: null needed alongside $exists: true?'), ("Query Debugging: A query { 'scores.math': { $gte: 80 }, 'scores.science': { $gte: 80 } } fails to ensure both are in the same exam entry. Fix it.", 'Use $elemMatch: { scores: { $elemMatch: { math: { $gte: 80 }, science: { $gte: 80 } } } }.', 'Intermediate', 'Debugging', '-- FIX:\ndb.students.find({\n  scores: { $elemMatch: { math: { $gte: 80 }, science: { $gte: 80 } } }\n});', 'Why was $elemMatch required?'), ('What is the MongoDB Aggregation Pipeline?', 'A framework for data transformation modeled as a multi-stage pipeline where documents pass through stages that filter, group, reshape, and calculate results.', 'Easy', 'Concept', "db.orders.aggregate([\n  { $match: { status: 'completed' } },\n  { $group: { _id: '$customerId', totalSpent: { $sum: '$total' } } }\n]);", 'What are the common aggregation pipeline stages?'), ('Name 7 core aggregation pipeline stages in MongoDB.', '$match (filter), $group (summarize), $project (reshape), $sort (order), $limit (constrain), $skip (offset), $unwind (deconstruct arrays).', 'Easy', 'Concept', '', 'What does the $match stage do?'), ('What does the $match stage do and where should it be placed in the pipeline?', '$match filters documents to pass only matching documents to the next stage. It should be placed as EARLY as possible in the pipeline to utilize indexes and reduce data volume.', 'Easy', 'Concept', "{ $match: { status: 'active', year: 2026 } }", 'Why should $match be first in pipeline?'), ('Why should $match and $sort be placed at the very start of an aggregation pipeline?', 'MongoDB can only use indexes to optimize $match and $sort if they appear at the beginning of the pipeline before any document restructuring stages (like $project or $group).', 'Intermediate', 'Performance', '', 'What does the $group stage do in aggregation?'), ('What does the $group stage do in MongoDB aggregation?', '$group separates documents into groups according to a specified group key (_id) and computes accumulator values (sum, avg, count) for each group.', 'Easy', 'Concept', "{ $group: { _id: '$category', totalSales: { $sum: '$price' }, avgPrice: { $avg: '$price' } } }", 'What does _id represent in $group?'), ("What does '_id: null' represent in a $group stage?", "'_id: null' groups all incoming documents together into a single global group (calculating grand totals across the entire collection).", 'Easy', 'Concept', "db.sales.aggregate([\n  { $group: { _id: null, totalRevenue: { $sum: '$amount' } } }\n]);", 'How do you count documents in a $group stage?'), ('How do you count documents within groups in MongoDB aggregation?', 'Use { $sum: 1 } or the $count accumulator: { count: { $sum: 1 } }.', 'Easy', 'Practical', "{ $group: { _id: '$dept', empCount: { $sum: 1 } } }", 'What does the $project stage do?'), ('What does the $project stage do in aggregation?', '$project reshapes documents by including, excluding, or renaming existing fields, and computing new calculated fields.', 'Easy', 'Practical', "{ $project: { fullName: { $concat: ['$firstName', ' ', '$lastName'] }, email: 1 } }", 'What is the difference between $project and $addFields?'), ('What is the difference between $project and $addFields ($set)?', '$project requires explicitly specifying all fields you want to retain. $addFields automatically preserves ALL existing fields and adds/overwrites only the specified new fields.', 'Easy', 'Comparison', "{ $addFields: { totalCost: { $add: ['$price', '$tax'] } } }", 'Why is $addFields cleaner than $project?'), ('What does the $unwind stage do in MongoDB aggregation?', '$unwind deconstructs an array field from input documents to output one document for EACH element of the array.', 'Intermediate', 'Concept', "-- If doc is: { name: 'A', tags: ['x', 'y'] }\n-- $unwind: '$tags' produces 2 docs:\n-- { name: 'A', tags: 'x' }\n-- { name: 'A', tags: 'y' }", 'What happens if an array is empty or missing when using $unwind?'), ('What happens to documents with null, empty, or missing arrays in $unwind and how do you preserve them?', 'By default, $unwind drops those documents! Pass { preserveNullAndEmptyArrays: true } to retain them with null values.', 'Intermediate', 'Concept', "{ $unwind: { path: '$tags', preserveNullAndEmptyArrays: true } }", 'What does $lookup stage do in MongoDB?'), ('What does the $lookup stage do in MongoDB?', '$lookup performs a left outer join to an unsharded collection in the same database, attaching matching documents as an array field.', 'Intermediate', 'Concept', "db.orders.aggregate([\n  {\n    $lookup: {\n      from: 'customers',\n      localField: 'customerId',\n      foreignField: '_id',\n      as: 'customerDetails'\n    }\n  }\n]);", "What data type is the 'as' output field in $lookup?"), ("What data type does the $lookup 'as' field always contain?", 'An Array of matching documents (even if only 0 or 1 document matches). Use $unwind to flatten the array to a single object.', 'Intermediate', 'Concept', '', 'What is correlated subquery with pipeline in $lookup?'), ('How do you write a complex join with custom filtering using $lookup in MongoDB?', "Use the pipeline form: $lookup: { from: '...', let: { var: '$field' }, pipeline: [ { $match: { ... } } ], as: '...' }.", 'Advanced', 'Practical', "{\n  $lookup: {\n    from: 'orders',\n    let: { custId: '$_id' },\n    pipeline: [\n      { $match: { $expr: { $and: [{ $eq: ['$customerId', '$$custId'] }, { $gt: ['$total', 100] }] } } }\n    ],\n    as: 'highValueOrders'\n  }\n}", 'What does $$ prefix mean in aggregation?'), ("What does '$$' prefix represent in MongoDB aggregation expressions?", "'$$' references variables defined in scopes (like variables defined in let: { var: '...' } or system variables like $$ROOT, $$CURRENT, $$NOW).", 'Intermediate', 'Concept', '', 'What does $$ROOT represent in aggregation?'), ('What is the $$ROOT system variable in MongoDB aggregation?', '$$ROOT references the entire top-level document currently being processed in the aggregation pipeline.', 'Intermediate', 'Concept', "{ $replaceRoot: { newRoot: '$embeddedDoc' } }", 'What does $count stage do?'), ('What does the $count stage do in an aggregation pipeline?', "It counts the total number of documents entering the stage and outputs a single document with that count: { $count: 'totalRecords' }.", 'Easy', 'Practical', "db.users.aggregate([\n  { $match: { status: 'active' } },\n  { $count: 'totalActive' }\n]);", 'What does $facet stage do in aggregation?'), ('What is the $facet stage in MongoDB aggregation?', '$facet allows running multiple independent aggregation pipelines on the same input documents within a single stage (ideal for multi-faceted search and simultaneous pagination + count).', 'Advanced', 'Architecture', "db.products.aggregate([\n  {\n    $facet: {\n      categorized: [{ $sortByCount: '$category' }],\n      paginatedResults: [{ $skip: 10 }, { $limit: 10 }],\n      totalCount: [{ $count: 'total' }]\n    }\n  }\n]);", 'How does $facet help with pagination?'), ('How does $facet solve pagination and total count in a single database round-trip?', 'One sub-pipeline runs $skip and $limit to fetch current page items, while another sub-pipeline runs $count to return total matching records simultaneously.', 'Advanced', 'Scenario', '', 'What is the memory limit for an aggregation pipeline stage?'), ('What is the RAM limit for aggregation pipeline stages in MongoDB and how do you bypass it?', 'Pipeline stages have a maximum RAM limit of 100MB (RAM). Pass { allowDiskUse: true } to allow spillover to temporary disk files for large sorts/groups.', 'Intermediate', 'Practical', 'db.largeCollection.aggregate(pipeline, { allowDiskUse: true });', 'Aggregation MCQ: Which stage performs a left outer join to another collection?'), ('Aggregation MCQ: Which pipeline stage performs a join to another collection in MongoDB?', 'Option B is correct. $lookup performs left outer joins.', 'Easy', 'MCQ', '', {'A': '$join', 'B': '$lookup', 'C': '$merge', 'D': '$connect'}, 'B', 'What does it output?'), ('Aggregation MCQ: Which stage deconstructs an array field into multiple documents?', 'Option C is correct. $unwind creates one document per array item.', 'Easy', 'MCQ', '', {'A': '$expand', 'B': '$split', 'C': '$unwind', 'D': '$flatten'}, 'C', 'What option prevents dropping empty arrays?'), ('Aggregation Coding: Calculate total revenue and average order value per customer from an orders collection.', "db.orders.aggregate([{ $group: { _id: '$customerId', totalRevenue: { $sum: '$total' }, avgOrderValue: { $avg: '$total' } } }]);", 'Easy', 'Coding', "db.orders.aggregate([\n  {\n    $group: {\n      _id: '$customerId',\n      totalRevenue: { $sum: '$totalAmount' },\n      avgOrderValue: { $avg: '$totalAmount' },\n      orderCount: { $sum: 1 }\n    }\n  },\n  { $sort: { totalRevenue: -1 } }\n]);", 'How do you filter only customers with > 5 orders?'), ('Aggregation Debugging: An aggregation with $lookup returns an empty array for joined docs despite matching IDs. Why?', 'Type mismatch: one collection stored the ID as a string, and the other stored it as an ObjectId! $lookup requires exact data type matching. Convert with $toObjectId.', 'Intermediate', 'Debugging', "-- FIX with $toObjectId:\n{\n  $addFields: { customerObjId: { $toObjectId: '$customerId' } }\n}", 'Why does string vs ObjectId break $lookup?'), ('What is an Index in MongoDB and why is it used?', "An index is a specialized B-tree data structure that stores a small portion of the collection's data set ordered by field values, allowing fast query resolution without full collection scans (COLLSCAN).", 'Easy', 'Concept', 'db.users.createIndex({ email: 1 });', 'What is a COLLSCAN vs IXSCAN?'), ('What is the difference between COLLSCAN and IXSCAN in MongoDB explain() plans?', 'COLLSCAN (Collection Scan) reads every document on disk sequentially (slow, O(N)). IXSCAN (Index Scan) seeks directly through index keys (fast, O(log N)).', 'Easy', 'Comparison', '', 'How do you create an index in MongoDB?'), ('How do you create a single-field index in MongoDB?', 'Run: db.collection.createIndex({ fieldName: 1 }); (1 for ascending, -1 for descending).', 'Easy', 'Practical', 'db.users.createIndex({ username: 1 });', 'How do you create a Unique Index?'), ('How do you enforce uniqueness on a field in MongoDB?', 'Create an index with { unique: true }: db.users.createIndex({ email: 1 }, { unique: true });.', 'Easy', 'Practical', 'db.users.createIndex({ email: 1 }, { unique: true });', 'What happens if duplicate values already exist when creating a unique index?'), ('What happens if you create a unique index on a collection that already contains duplicate keys?', 'The index creation fails and throws a DuplicateKeyError (E11000). You must clean up duplicates before creating the index.', 'Intermediate', 'Debugging', '', 'What is a Compound Index in MongoDB?'), ('What is a Compound Index in MongoDB and does field order matter?', 'A compound index indexes multiple fields together: createIndex({ department: 1, salary: -1 }). Field order strictly matters: it adheres to the Equality, Sort, Range (ESR) rule.', 'Intermediate', 'Concept', 'db.employees.createIndex({ department: 1, salary: -1 });', 'What is the ESR (Equality, Sort, Range) rule for compound indexes?'), ('What is the ESR (Equality, Sort, Range) rule for optimal compound index design in MongoDB?', 'Place fields queried with exact equality first (E), fields used for sorting second (S), and fields queried with range operators (<, >, $in) last (R).', 'Advanced', 'Best Practice', "-- For query: find({ dept: 'IT', age: { $gte: 25 } }).sort({ salary: -1 })\n-- Optimal Index: { dept: 1, salary: -1, age: 1 }", 'Why place Sort before Range?'), ('What is a Multikey Index in MongoDB?', 'An index on an array field. MongoDB creates an index entry for every single element in the array automatically.', 'Intermediate', 'Concept', 'db.products.createIndex({ tags: 1 });', 'Can a compound multikey index contain more than one array field?'), ('Can a compound index cover more than one array field in MongoDB?', "No! A compound multikey index cannot index more than one array field per document (throws an error: 'cannot index parallel arrays').", 'Advanced', 'Concept', '', 'What is a TTL (Time-To-Live) Index in MongoDB?'), ('What is a TTL (Time-To-Live) Index and what is it used for?', 'A single-field index that automatically deletes documents after a specified number of seconds based on a Date field (ideal for sessions, OTPs, cache expiry).', 'Easy', 'Concept', 'db.sessions.createIndex({ createdAt: 1 }, { expireAfterSeconds: 3600 });', 'What data type must the TTL index field have?'), ('What data type must a TTL index field be in MongoDB?', 'It MUST be a BSON Date object (new Date()). If the field is not a Date or is missing, the document will not expire.', 'Intermediate', 'Concept', '', 'What is a Text Index in MongoDB?'), ('What is a Text Index and what query operator searches it?', "A text index supports full-text search over string content with stemming and stop-word removal. Searched using the $text operator: find({ $text: { $search: 'database' } }).", 'Intermediate', 'Practical', "db.articles.createIndex({ title: 'text', content: 'text' });\ndb.articles.find({ $text: { $search: 'node mongodb' } });", 'How many text indexes can a collection have?'), ('How many text indexes can exist on a single MongoDB collection?', 'At most ONE text index per collection. However, that single text index can cover multiple string fields (compound text index).', 'Intermediate', 'Concept', '', 'What is a Partial Index in MongoDB?'), ('What is a Partial Index in MongoDB?', 'An index that only indexes documents satisfying a specified filter expression: createIndex({ email: 1 }, { partialFilterExpression: { isVerified: true } }). Saves RAM.', 'Intermediate', 'Concept', 'db.users.createIndex({ email: 1 }, { unique: true, partialFilterExpression: { email: { $exists: true } } });', 'How does a Sparse Index differ from a Partial Index?'), ('What is the difference between a Sparse Index and a Partial Index?', 'Sparse index only indexes documents where the indexed field exists (obsolete). Partial index is the modern replacement allowing arbitrary filter conditions.', 'Intermediate', 'Comparison', '', "What does explain('executionStats') do in MongoDB?"), ('How do you inspect query execution performance and index usage in MongoDB?', "Append .explain('executionStats') to the query: db.users.find({ email: '...' }).explain('executionStats'). Look at stage (IXSCAN vs COLLSCAN) and totalDocsExamined.", 'Easy', 'Debugging', "db.users.find({ email: 'test@example.com' }).explain('executionStats');", 'What ratio of totalDocsExamined to nReturned indicates a healthy query?'), ('What is the ideal ratio between totalDocsExamined and nReturned in executionStats?', 'Ideally 1:1. If totalDocsExamined is 10,000 and nReturned is 1, the query is performing a slow collection scan and desperately needs an index.', 'Intermediate', 'Performance', '', 'What is Embedding (Denormalization) vs Referencing (Normalization) in MongoDB schema design?'), ('What is the difference between Embedding and Referencing in MongoDB data modeling?', 'Embedding: Storing related data as nested subdocuments/arrays inside the same document (1:1 or 1:few). Referencing: Storing documents in separate collections and linking them via ObjectIds (1:many or many:many).', 'Easy', 'Comparison', "-- Embedding: { name: 'A', address: { city: 'NY' } }\n-- Referencing: { name: 'A', addressId: ObjectId('...') }", 'When should you EMBED data in MongoDB?'), ('When should you choose Embedding over Referencing in MongoDB?', '1. Data is accessed together in queries (read together, stored together). 2. 1-to-1 or bounded 1-to-few relationships (e.g. user address, order items). 3. Atomic document updates needed.', 'Easy', 'Best Practice', '', 'When should you choose REFERENCING over Embedding in MongoDB?'), ('When should you choose Referencing over Embedding in MongoDB?', '1. Unbounded 1-to-many relationships (e.g. millions of sensor logs for a device). 2. Many-to-many relationships (students & courses). 3. Data is updated frequently and independently.', 'Easy', 'Best Practice', '', "What is the 'Unbounded Array' anti-pattern in MongoDB?"), ('What is the Unbounded Array Anti-Pattern in MongoDB schema design?', 'Pushing unbounded elements (like comments or logs) into an array inside a parent document. The document eventually exceeds the 16MB limit and causes severe B-tree re-allocation page fragmentation.', 'Intermediate', 'Scenario', '', 'How do you model comments in a blog post to avoid the 16MB document limit?'), ('How should high-volume comments on a popular post be modeled in MongoDB?', "Store comments in a separate 'comments' collection referencing postId: { _id, postId: ObjectId('...'), text, author }, allowing infinite comments with pagination.", 'Intermediate', 'Architecture', '', 'What are Mongoose Virtuals?'), ('What are Virtuals in Mongoose?', 'Document properties that can be gotten and set but are NOT persisted to MongoDB storage (computed properties, e.g. fullName from firstName + lastName).', 'Easy', 'Concept', "userSchema.virtual('fullName').get(function() {\n  return `${this.firstName} ${this.lastName}`;\n});", 'What is Mongoose Middleware (Hooks)?'), ('What are Mongoose Pre and Post middleware hooks?', "Functions passed control during the execution of asynchronous operations (e.g. pre('save') to hash passwords with bcrypt before saving to database).", 'Easy', 'Practical', "userSchema.pre('save', async function(next) {\n  if (this.isModified('password')) {\n    this.password = await bcrypt.hash(this.password, 10);\n  }\n  next();\n});", "What does doc.isModified('field') do in Mongoose?"), ("What does doc.isModified('password') do in Mongoose pre-save hooks?", 'It checks if the password field was modified in the current operation, preventing re-hashing an already-hashed password when updating other fields like email.', 'Easy', 'Security', '', 'What does mongoose.populate() do?'), ('What does the Mongoose populate() method do?', 'It replaces specified ObjectId reference fields in a document with the actual document(s) from the referenced collection (emulates a join in application code).', 'Easy', 'Practical', "const order = await Order.findById(id).populate('customer');\nconsole.log(order.customer.name);", 'What is the performance drawback of Mongoose populate()?'), ('What is the performance drawback of Mongoose populate() compared to $lookup?', 'populate() executes multiple separate queries under the hood (one to fetch the order, then another to fetch customers), causing N+1 query overhead for arrays.', 'Intermediate', 'Performance', '', 'What does .lean() do in Mongoose queries?'), ('What does .lean() do in Mongoose queries and why is it faster?', 'By default, Mongoose wraps query results in heavy Mongoose Document instances with change tracking and getters. .lean() returns plain JavaScript objects, speeding up reads by up to 5x.', 'Intermediate', 'Performance', 'const users = await User.find().lean();', 'When should .lean() NOT be used?'), ('When should you NOT use .lean() in Mongoose?', 'When you need to modify the document and call doc.save(), or when you rely on Mongoose virtuals, getters, or custom instance methods.', 'Intermediate', 'Concept', '', 'Performance MCQ: What explain plan stage indicates a full collection scan without index?'), ('Performance MCQ: What stage in MongoDB explain() output indicates that no index was used?', 'Option A is correct. COLLSCAN indicates a full collection scan.', 'Easy', 'MCQ', '', {'A': 'COLLSCAN', 'B': 'IXSCAN', 'C': 'FETCH', 'D': 'INDEX_LOOKUP'}, 'A', 'What stage indicates an index seek?'), ("Mongoose Coding: Write a Mongoose pre('save') hook that automatically updates an 'updatedAt' field.", "schema.pre('save', function(next) { this.updatedAt = new Date(); next(); });", 'Easy', 'Coding', "userSchema.pre('save', function(next) {\n  this.updatedAt = new Date();\n  next();\n});", "Does findOneAndUpdate trigger pre('save') hooks?"), ("Does findOneAndUpdate trigger Mongoose pre('save') hooks?", "No! findOneAndUpdate() bypasses document middleware and executes directly on the database. It triggers pre('findOneAndUpdate') query middleware instead.", 'Intermediate', 'Concept', '', 'What hook fires on updateOne?'), ('Performance Debugging: A TTL index was created with expireAfterSeconds: 60, but documents are not deleted immediately after 60 seconds. Why?', 'The background TTL cleanup thread runs once every 60 seconds. Documents expire and are deleted during the next scheduled run (may take up to 60-120 seconds).', 'Intermediate', 'Debugging', '-- This is normal: background thread runs periodically', 'How do you force immediate expiration in tests?'), ('Does MongoDB support multi-document ACID transactions?', 'Yes! Starting in version 4.0 (replica sets) and 4.2 (sharded clusters), MongoDB supports multi-document ACID transactions using sessions.', 'Easy', 'Concept', 'const session = client.startSession();\nsession.startTransaction();', 'What are the performance costs of multi-document transactions?'), ('Why should multi-document transactions be used sparingly in MongoDB?', 'Transactions hold locks on modified documents, consume server cache memory, and incur latency overhead. Document embedding should be the primary pattern for atomic writes.', 'Intermediate', 'Best Practice', '', 'How do you execute a transaction in Mongoose?'), ('How do you execute a transaction in Mongoose with Node.js?', 'Start a session, wrap queries in session.withTransaction(), and pass { session } option to each operation.', 'Intermediate', 'Practical', 'const session = await mongoose.startSession();\nawait session.withTransaction(async () => {\n  await Account.updateOne({ _id: fromId }, { $inc: { balance: -100 } }, { session });\n  await Account.updateOne({ _id: toId }, { $inc: { balance: 100 } }, { session });\n});\nsession.endSession();', 'What happens if an error is thrown inside withTransaction?'), ('What happens if an exception is thrown inside session.withTransaction()?', 'MongoDB automatically aborts the transaction, rolls back all changes, and closes open locks automatically.', 'Easy', 'Concept', '', 'What is the maximum execution time limit for a MongoDB transaction?'), ('What is the default transaction lifetime limit in MongoDB?', 'The default transaction lifetime is 60 seconds (transactionLifetimeLimitSeconds). Transactions open longer than 60 seconds are automatically aborted.', 'Intermediate', 'Concept', '', 'Transactions MCQ: Which method starts an ACID transaction on a client session in MongoDB?'), ('Transactions MCQ: Which method initiates a transaction in the MongoDB driver?', 'Option B is correct. session.startTransaction() starts an ACID transaction.', 'Easy', 'MCQ', '', {'A': 'db.beginTransaction()', 'B': 'session.startTransaction()', 'C': 'client.transaction()', 'D': 'db.startACID()'}, 'B', 'What ends the session?'), ('Transactions MCQ: What happens if an unhandled error occurs within session.withTransaction()?', 'Option C is correct. The transaction is automatically aborted and changes rolled back.', 'Easy', 'MCQ', '', {'A': 'Changes are partially committed', 'B': 'Database hangs', 'C': 'Transaction automatically aborts and rolls back', 'D': 'Retried indefinitely'}, 'C', 'How do you handle retries?'), ('Transactions Coding: Write a money transfer between two accounts using MongoDB transactions.', 'const session = client.startSession(); await session.withTransaction(async () => { await accounts.updateOne({ _id: a }, { $inc: { bal: -50 } }, { session }); await accounts.updateOne({ _id: b }, { $inc: { bal: 50 } }, { session }); }); session.endSession();', 'Intermediate', 'Coding', 'async function transfer(fromId, toId, amount) {\n  const session = client.startSession();\n  try {\n    await session.withTransaction(async () => {\n      await accounts.updateOne({ _id: fromId }, { $inc: { balance: -amount } }, { session });\n      await accounts.updateOne({ _id: toId }, { $inc: { balance: amount } }, { session });\n    });\n  } finally {\n    await session.endSession();\n  }\n}', 'Why is session.endSession() placed in a finally block?'), ('Why must session.endSession() be placed in a finally block?', 'To guarantee that the session is always closed and server resources are released, even if the transaction fails with an unhandled exception.', 'Easy', 'Best Practice', '', 'What is Read Concern in MongoDB transactions?'), ("What is Read Concern 'snapshot' in MongoDB transactions?", 'It guarantees that all reads within the transaction see a consistent, isolated point-in-time snapshot of the data, unaffected by concurrent writes.', 'Advanced', 'Concept', '', 'What is Change Streams in MongoDB?'), ('What are Change Streams in MongoDB?', 'Change Streams allow applications to subscribe to real-time data changes (inserts, updates, deletes) in a collection, database, or deployment using the oplog.', 'Intermediate', 'Concept', "const changeStream = collection.watch();\nchangeStream.on('change', next => console.log(next));", 'What requirement must be met to use Change Streams?'), ('What is the prerequisite for using Change Streams in MongoDB?', 'The MongoDB deployment MUST be a Replica Set or Sharded Cluster because Change Streams rely on the oplog.', 'Intermediate', 'Concept', '', "How do you filter Change Streams to only watch for 'insert' operations?"), ('How do you filter a Change Stream for specific operations?', "Pass an aggregation pipeline to .watch(): collection.watch([ { $match: { operationType: 'insert' } } ]).", 'Intermediate', 'Practical', "const stream = db.orders.watch([\n  { $match: { operationType: 'insert', 'fullDocument.total': { $gt: 100 } } }\n]);", 'What information does a change stream event contain?'), ('What does a Change Stream event object contain?', "operationType ('insert', 'update', 'delete', 'replace'), documentKey (the _id), fullDocument, updateDescription (updated fields), and clusterTime.", 'Intermediate', 'Concept', '', 'What is resumeToken in Change Streams?'), ('What is a resumeToken (_id) in Change Streams?', 'An opaque token returned with each change event that allows an application to resume listening from the exact last processed event after network downtime.', 'Advanced', 'Architecture', 'collection.watch([], { resumeAfter: lastResumeToken });', 'How does this prevent missed events?'), ('Change Streams MCQ: What cluster architecture is required to use MongoDB Change Streams?', 'Option B is correct. A Replica Set or Sharded Cluster is mandatory.', 'Easy', 'MCQ', '', {'A': 'Standalone mongod', 'B': 'Replica Set or Sharded Cluster', 'C': 'WiredTiger single instance', 'D': 'GridFS deployment'}, 'B', 'Why is it required?'), ("Change Streams Coding: Watch the 'messages' collection and log newly inserted chat messages in real time.", "const stream = messages.watch([{ $match: { operationType: 'insert' } }]); stream.on('change', change => console.log('New message:', change.fullDocument.text));", 'Easy', 'Coding', "const stream = db.collection('messages').watch([\n  { $match: { operationType: 'insert' } }\n]);\nstream.on('change', change => {\n  console.log('New chat message:', change.fullDocument);\n});", 'How do you close a change stream?'), ('What is GeoJSON in MongoDB?', "A standard format for encoding geographic data structures (Point, LineString, Polygon) using coordinates: { type: 'Point', coordinates: [longitude, latitude] }.", 'Easy', 'Concept', "{ location: { type: 'Point', coordinates: [-73.97, 40.77] } }", 'Why is coordinates order longitude then latitude?'), ('What is the order of coordinates in MongoDB GeoJSON?', 'Strictly [Longitude, Latitude] (X, Y axis order). Reversing them causes queries to look in the wrong hemisphere!', 'Easy', 'Best Practice', 'coordinates: [longitude, latitude]', 'What index type is used for GeoJSON queries?'), ('What index type supports geospatial queries on a sphere in MongoDB?', "The '2dsphere' index: db.places.createIndex({ location: '2dsphere' }).", 'Easy', 'Concept', "db.restaurants.createIndex({ location: '2dsphere' });", 'What does $near operator do in geospatial queries?'), ('What does the $near operator do in MongoDB geospatial queries?', 'It finds documents nearest to a specified GeoJSON point and sorts them by distance from closest to farthest automatically.', 'Intermediate', 'Practical', "db.places.find({\n  location: {\n    $near: {\n      $geometry: { type: 'Point', coordinates: [-73.96, 40.78] },\n      $maxDistance: 1000 // In meters\n    }\n  }\n});", 'What does $geoWithin operator do?'), ('What is the difference between $near and $geoWithin in MongoDB?', '$near sorts results by distance and requires an index. $geoWithin selects documents inside a bounding polygon or circle without sorting by distance.', 'Intermediate', 'Comparison', '', 'What is a Wildcard Index ($**) in MongoDB?'), ('What is a Wildcard Index ($**) in MongoDB?', "An index that indexes all fields in dynamic or unpredictable user-defined attribute schemas: createIndex({ 'customAttributes.$**': 1 }).", 'Advanced', 'Concept', "db.products.createIndex({ 'attributes.$**': 1 });", 'When should Wildcard indexes be used?'), ('When are Wildcard indexes useful?', 'In e-commerce product catalogs where different categories have completely different, dynamic custom attributes (e.g. shirt size vs TV screen resolution).', 'Intermediate', 'Scenario', '', 'What is a Clustered Collection in MongoDB (v5.3+)?'), ('What is a Clustered Collection in MongoDB v5.3+?', 'A collection stored ordered by a clustered index key (similar to SQL clustered tables), improving insert performance and range scan speed.', 'Advanced', 'Concept', "db.createCollection('logs', { clusteredIndex: { key: { _id: 1 }, unique: true } });", 'Geospatial MCQ: What coordinate order does MongoDB GeoJSON require?'), ('Geospatial MCQ: What is the correct order of coordinates in a GeoJSON Point?', 'Option A is correct. [longitude, latitude].', 'Easy', 'MCQ', '', {'A': '[longitude, latitude]', 'B': '[latitude, longitude]', 'C': '[altitude, latitude]', 'D': '[x, y, z]'}, 'A', 'What happens if reversed?'), ('Geospatial MCQ: Which index type is required for spherical Earth distance calculations in MongoDB?', 'Option C is correct. 2dsphere index calculates spherical distance.', 'Easy', 'MCQ', '', {'A': '2d', 'B': 'geo', 'C': '2dsphere', 'D': 'spatial'}, 'C', 'What is 2d used for?'), ('Geospatial Coding: Find all coffee shops within 500 meters of a coordinate.', "db.shops.find({ location: { $near: { $geometry: { type: 'Point', coordinates: [lng, lat] }, $maxDistance: 500 } } });", 'Easy', 'Coding', "db.shops.find({\n  location: {\n    $near: {\n      $geometry: { type: 'Point', coordinates: [77.5946, 12.9716] },\n      $maxDistance: 500\n    }\n  }\n});", 'What unit is maxDistance in?'), ('What are Mongoose Discriminators?', 'A schema inheritance mechanism that allows storing different model schemas in the same underlying MongoDB collection with a __t type key.', 'Intermediate', 'Concept', "const Event = mongoose.model('Event', eventSchema);\nconst ClickedEvent = Event.discriminator('Clicked', new mongoose.Schema({ url: String }));", 'When are discriminators useful?'), ('When should you use Mongoose Discriminators?', 'When you have shared common fields across polymorphic entities (e.g. Notification base model with EmailNotification and PushNotification variants).', 'Intermediate', 'Scenario', '', 'What is deep population in Mongoose?'), ('How do you perform Deep Population across multiple levels in Mongoose?', "Pass a nested populate object: populate({ path: 'author', populate: { path: 'profile' } }).", 'Intermediate', 'Practical', "const post = await Post.findById(id).populate({\n  path: 'comments',\n  populate: { path: 'author', select: 'name avatar' }\n});", 'What performance risk exists with deep population?'), ('Why should deep population across 3+ levels be avoided in high-traffic APIs?', 'Each populate level executes additional database queries, leading to severe latency and N+1 query bottlenecks. Use aggregation $lookup instead.', 'Intermediate', 'Performance', '', 'What is Mongoose timestamps option?'), ('What does { timestamps: true } in a Mongoose schema do?', 'It automatically adds and manages createdAt and updatedAt Date fields on every document.', 'Easy', 'Practical', 'const userSchema = new mongoose.Schema({ name: String }, { timestamps: true });', 'Can createdAt be modified by users?'), ('How do you soft-delete documents in Mongoose?', "Add an isDeleted: Boolean (or deletedAt: Date) field, and filter queries with pre('find') middleware: this.where({ isDeleted: false }).", 'Easy', 'Practical', 'schema.pre(/^find/, function(next) {\n  this.where({ isDeleted: false });\n  next();\n});', 'Why is soft deletion common in SaaS applications?'), ('Mongoose MCQ: Which schema option automatically manages createdAt and updatedAt fields?', 'Option B is correct. timestamps: true automatically adds both fields.', 'Easy', 'MCQ', '', {'A': 'autoDate: true', 'B': 'timestamps: true', 'C': 'audit: true', 'D': 'trackTime: true'}, 'B', 'What types are the fields?'), ("Mongoose Debugging: A developer called await User.updateOne({ _id }, { $set: { password: '123' } }) but the pre('save') hash hook didn't fire. Why?", "updateOne() is a query-level operation that bypasses document-level pre('save') hooks. Use user = await User.findById(); user.password = '123'; await user.save();.", 'Intermediate', 'Debugging', "-- FIX:\nconst user = await User.findById(id);\nuser.password = newPassword;\nawait user.save(); // pre('save') fires and hashes password!", 'What hook fires on updateOne?'), ('What is MongoDB Atlas?', "MongoDB Atlas is MongoDB's fully managed multi-cloud database-as-a-service (DBaaS), offering automated backups, scaling, monitoring, and security patching.", 'Easy', 'Concept', '', 'What is the standard MongoDB connection string URI format?'), ('What does a mongodb+srv:// connection URI indicate?', "The 'mongodb+srv://' prefix uses DNS SRV records to automatically discover all replica set nodes without listing each host IP individually in the URI.", 'Easy', 'Concept', 'mongodb+srv://user:pass@cluster0.mongodb.net/myDB?retryWrites=true&w=majority', 'Why is mongodb+srv preferred over standard mongodb://?')]

def build_sql_pack(start_num=1):
    qs = []
    num = start_num
    for item in SQL_ITEMS:
        q_text, ans, diff, qtype, code, mcq_opts, correct_opt, fup = parse_item(item)
        qs.append(make_q(
            f"q-sql-{num}", num, "SQL", "SQL & Relational Databases", "Queries, Joins, Aggregation & Design",
            q_text, ans, difficulty=diff, question_type=qtype,
            code_example=code, follow_up=fup,
            mcq_options=mcq_opts, correct_option=correct_opt
        ))
        num += 1
    return qs

def build_mongodb_pack(start_num=1):
    qs = []
    num = start_num
    for item in MONGO_ITEMS:
        q_text, ans, diff, qtype, code, mcq_opts, correct_opt, fup = parse_item(item)
        qs.append(make_q(
            f"q-mongo-{num}", num, "MongoDB", "NoSQL & MongoDB", "CRUD, Aggregation, Indexing & Modeling",
            q_text, ans, difficulty=diff, question_type=qtype,
            code_example=code, follow_up=fup,
            mcq_options=mcq_opts, correct_option=correct_opt
        ))
        num += 1
    return qs
